                                       className={`p-4 rounded-2xl border-2 font-black text-xs transition-all ${sundayOffs.includes(num) ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white text-slate-400 hover:border-slate-300'}`}
