const FloorDetailView: React.FC<FloorDetailViewProps> = ({ floor, theme, apartments, onBack, onSelectApartment }) => {
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});
  const [showFilters, setShowFilters] = useState(false);
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({ 'status': true });

  const baseApartmentNumbers = Array.from({ length: 35 }, (_, i) => floor + i)
    .filter(num => num !== 234 && num !== 417);

  const toggleSection = (id: string) => {
    setExpandedSections(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const filteredApartmentNumbers = useMemo(() => {
    return baseApartmentNumbers.filter(num => {
      const id = `${floor}-${num}`;
      const apt = apartments[id];

      return Object.entries(activeFilters).every(([key, value]) => {
        if (!value) return true;

        // 1. Status Geral
        if (key === 'status_geral') {
          const hasDefects = (apt?.defects?.length || 0) > 0;
          const isUrgent = apt?.pisoStatus === 'Reparo urgente' || apt?.banheiroStatus === 'Reparo urgente';
          if (value === 'Com Avaria') return hasDefects;
          if (value === 'Urgente') return isUrgent;
          if (value === 'Sem Avaria') return !hasDefects && !isUrgent;
        }

        if (!apt) return false; // Se o apto não foi inicializado, não passa nos filtros detalhados abaixo

        // 2. Lógica de Camas (Complexa)
        if (key.startsWith('bed_')) {
          if (!apt.beds || apt.beds.length === 0) return false;

          if (key === 'bed_type') return apt.beds.some(b => b.type === value);
          if (key === 'bed_base_status') return apt.beds.some(b => b.baseStatus === value);
          if (key === 'bed_mattress_status') return apt.beds.some(b => b.mattressStatus === value);
          if (key === 'bed_has_skirt') return apt.beds.some(b => (value === 'Sim' ? b.hasSkirt : !b.hasSkirt));
          return true;
        }

        // 3. Lógica de Arrays (Ex: Móveis Danificados)
        if (key === 'moveisDetalhes') {
          return apt.moveisDetalhes?.includes(value);
        }

        // 4. Lógica Booleana (Sim/Não)
        if (['temCortina', 'temCofre', 'temPortaControle', 'temEspelhoCorpo', 'temCabide', 'temSuporteShampoo', 'temSuportePapel'].includes(key)) {
          const boolValue = value === 'Sim';
          // @ts-ignore - Dynamic access
          return apt[key] === boolValue;
        }

        // 5. Comparação Direta (Strings)
        // @ts-ignore - Dynamic access
        return apt[key] === value;
      });
    });
  }, [baseApartmentNumbers, apartments, floor, activeFilters]);

  const toggleFilter = (key: string, value: string) => {
    setActiveFilters(prev => {
      const next = { ...prev };
      if (next[key] === value) {
        delete next[key];
      } else {
        next[key] = value;
      }
      return next;
    });
  };

  return (
    <div className="space-y-4 md:space-y-6">
      <div className="flex flex-row items-center justify-between gap-2 mb-4">
        <div className="flex items-center space-x-2">
          <button 
            onClick={onBack}
            className="p-2 hover:bg-slate-200 rounded-xl transition-colors text-slate-600 bg-white shadow-sm md:shadow-none"
          >
            <ChevronLeft size={20} />
          </button>
          <div>
            <h2 className="text-lg md:text-2xl font-black text-slate-800">Andar {floor}</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase">{filteredApartmentNumbers.length} Unidades</p>
          </div>
        </div>

        <button 
          onClick={() => setShowFilters(!showFilters)}
          className={`flex items-center space-x-2 px-4 py-2.5 rounded-xl font-bold transition-all border-2 text-xs shadow-sm ${
            showFilters || Object.keys(activeFilters).length > 0
              ? 'bg-slate-800 border-slate-800 text-white' 
              : 'bg-white border-slate-100 text-slate-600'
          }`}
        >
          <Filter size={14} />
          <span>Filtros {Object.keys(activeFilters).length > 0 && `(${Object.keys(activeFilters).length})`}</span>
        </button>
      </div>

      {/* Mobile-Friendly Filter Modal/Overlay */}
      {showFilters && (
        <div className="fixed inset-0 bg-slate-900/50 z-50 flex justify-end" onClick={() => setShowFilters(false)}>
           <div 
             className="w-full max-w-sm h-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300"
             onClick={e => e.stopPropagation()}
           >
              <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                 <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight flex items-center gap-2">
                    <Filter size={18} /> Filtros
                 </h3>
                 <button onClick={() => setShowFilters(false)} className="p-2 bg-white rounded-full text-slate-400 shadow-sm"><X size={20}/></button>
              </div>

              <div className="flex-1 overflow-y-auto p-6 space-y-6">
                 {Object.keys(activeFilters).length > 0 && (
                    <div className="flex justify-end">
                      <button 
                        onClick={() => setActiveFilters({})}
                        className="text-[10px] font-black text-red-500 flex items-center space-x-1 hover:underline bg-red-50 px-3 py-1.5 rounded-lg"
                      >
                        <X size={12} />
                        <span>LIMPAR FILTROS ATIVOS</span>
                      </button>
                    </div>
                  )}

                 {FILTER_SECTIONS.map(section => {
                    const isExpanded = expandedSections[section.id];
                    const hasActiveFilter = section.filters.some(f => activeFilters[f.key]);
                    const Icon = section.icon;

                    return (
                       <div key={section.id} className={`border border-slate-100 rounded-2xl overflow-hidden transition-all ${hasActiveFilter ? 'ring-2 ring-blue-100' : ''}`}>
                          <button 
                            onClick={() => toggleSection(section.id)}
                            className="w-full p-4 bg-slate-50 flex items-center justify-between"
                          >
                             <div className="flex items-center space-x-3">
                                <Icon size={18} className={section.color} />
                                <span className={`text-xs font-black uppercase tracking-wide ${hasActiveFilter ? 'text-slate-800' : 'text-slate-500'}`}>{section.label}</span>
                             </div>
                             {isExpanded ? <ChevronUp size={16} className="text-slate-400"/> : <ChevronDown size={16} className="text-slate-400"/>}
                          </button>

                          {isExpanded && (
                             <div className="p-4 bg-white space-y-4">
                                {section.filters.map(filter => (
                                   <div key={filter.key}>
                                      <p className="text-[9px] font-black text-slate-300 uppercase mb-2 ml-1">{filter.label}</p>
                                      <div className="flex flex-wrap gap-2">
                                         {filter.options.map(opt => (
                                            <button
                                               key={opt}
                                               onClick={() => toggleFilter(filter.key, opt)}
                                               className={`px-3 py-2 rounded-xl text-[10px] font-bold border transition-all ${
                                                  activeFilters[filter.key] === opt
                                                  ? 'bg-slate-800 border-slate-800 text-white shadow-md'
                                                  : 'bg-white border-slate-100 text-slate-500 hover:border-slate-300'
                                               }`}
                                            >
                                               {opt}
                                            </button>
                                         ))}
                                      </div>
                                   </div>
                                ))}
                             </div>
                          )}
                       </div>
                    );
                 })}
              </div>

              <div className="p-6 border-t border-slate-100 bg-slate-50">
                 <button 
                   onClick={() => setShowFilters(false)} 
                   className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl active:scale-95 transition-all"
                 >
                    Ver {filteredApartmentNumbers.length} Resultados
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* Apartment Grid */}
      <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-7 gap-3 md:gap-4 pb-20">
        {filteredApartmentNumbers.map((num) => {
          const id = `${floor}-${num}`;
          const aptData = apartments[id];
          const isInitialized = !!aptData;

          // Lógica de Alerta Visual
          const hasDefects = isInitialized && aptData.defects.length > 0;
          const isUrgent = isInitialized && (
            aptData.pisoStatus === 'Reparo urgente' || 
            aptData.banheiroStatus === 'Reparo urgente'
          );

          // Prioridade: Com Avaria/Urgente (Vermelho) > Normal (Verde) > Não Iniciado (Cinza)
          const needsAttention = hasDefects || isUrgent;

          return (
            <button
              key={num}
              onClick={() => onSelectApartment(id)}
              className={`relative h-28 md:h-32 rounded-2xl border-2 flex flex-col items-center justify-center transition-all duration-200 active:scale-95 shadow-sm ${
                !isInitialized
                ? 'bg-slate-50 border-slate-200 text-slate-400'
                : needsAttention 
                ? 'bg-red-50 border-red-500 text-red-800' 
                : 'bg-green-50 border-green-500 text-green-800'
              }`}
            >
              <span className="text-[8px] font-black opacity-60 uppercase tracking-tighter mb-0.5">Apto</span>
              <span className="text-xl md:text-2xl font-black">{num}</span>

              <div className="mt-1">
                {!isInitialized ? (
                  <div className="w-3.5 h-3.5 rounded-full border-2 border-slate-200 opacity-50" />
                ) : needsAttention ? (
                  isUrgent ? <AlertTriangle size={14} className="text-red-600 animate-pulse" /> : <AlertCircle size={14} className="text-red-500" />
                ) : (
                  <CheckCircle2 size={14} className="text-green-500" />
                )}
              </div>

              {!isInitialized && (
                <span className="absolute bottom-2 text-[6px] font-black uppercase opacity-40">Pendente</span>
              )}

              {/* Badges de Contagem */}
              {hasDefects && (
                <span className="absolute -top-1.5 -right-1.5 w-5 h-5 bg-red-600 text-white text-[9px] font-black flex items-center justify-center rounded-full border-2 border-white shadow-sm z-10">
                  {aptData.defects.length}
                </span>
              )}

              {/* Badge de Urgente se não tiver defeitos mas tiver urgência */}
              {!hasDefects && isUrgent && (
                 <span className="absolute -top-1.5 -right-1.5 w-5 h-5 bg-red-600 text-white text-[9px] font-black flex items-center justify-center rounded-full border-2 border-white shadow-sm z-10">
                   !
                 </span>
              )}
            </button>
          );
        })}
        {filteredApartmentNumbers.length === 0 && (
          <div className="col-span-full py-16 text-center text-slate-300 italic font-bold text-sm">
            Nenhum resultado para os filtros selecionados.
          </div>
        )}
      </div>
    </div>
  );
};

