                 </div>
              ))}
              {suppliers.length === 0 && <div className="col-span-full py-20 text-center text-slate-300 italic font-bold border-2 border-dashed rounded-[3rem]">Nenhum fornecedor cadastrado.</div>}
           </div>
        </div>
      )}


      {/* Modal NOVO ITEM */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">{editingItem ? 'Editar Insumo' : 'Novo Insumo'}</h2>
                 <p className="text-[10px] font-black text-slate-400 uppercase">{currentSector?.name}</p>
                 <button onClick={resetItemForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveItemSubmit} className="p-8 space-y-4">
                 <div className="grid grid-cols-1 gap-4">
                    <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none font-bold" placeholder="Nome do Insumo" required />
                    <div className="relative">
                       <Barcode size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" />
                       <input type="text" value={ean} onChange={e => setEan(e.target.value)} className="w-full pl-10 pr-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Código EAN (Obrigatório)" required />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                       <select value={category} onChange={e => setCategory(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold">
                          {categories.map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                       <select value={unit} onChange={e => setUnit(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold">
                          <option value="Unidade">Unidade</option>
                          <option value="Caixa">Caixa</option>
                          <option value="Litro">Litro</option>
                          <option value="Kg">Kg</option>
                       </select>
                    </div>
                    <select value={supplierId} onChange={e => setSupplierId(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold">
                       <option value="">Selecione o Fornecedor...</option>
                       {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                    <div className="grid grid-cols-2 gap-4">
                       <div className="p-4 bg-slate-50 rounded-2xl">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">Saldo Inicial</label>
                          <input type="number" value={initialQuantity} onChange={e => setInitialQuantity(parseInt(e.target.value) || 0)} className="w-full bg-transparent text-xl font-black outline-none" />
                       </div>
                       <div className="p-4 bg-slate-50 rounded-2xl">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">R$ Valor Unitário</label>
                          <input type="number" step="0.01" value={price} onChange={e => setPrice(parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-xl font-black outline-none" />
                       </div>
                    </div>
                 </div>
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl" style={{ backgroundColor: theme.primary }}>Salvar Cadastro</button>
              </form>
           </div>
        </div>
      )}

      {/* ... (MOVIMENTAÇÃO and FORNECEDOR modals remain the same) ... */}
      {isAddingOp && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           {/* ... Same Op Modal content as before ... */}
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">Lançar Movimentação</h2>
                 <button onClick={resetOpForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                const selectedItem = inventory.find(i => i.id === opItemId);
                if (!selectedItem || opQuantity <= 0) return;

                const finalRecipientName = opRecipientName || (opType === 'Saída' ? 'Não Identificado' : '');

                onOperation({ 
                    id: Date.now().toString(), 
                    itemId: opItemId, 
                    itemName: selectedItem.name, 
                    type: opType, 
                    quantity: opQuantity, 
                    timestamp: Date.now(), 
                    user: currentUser || 'Sistema', 
                    reason: opReason,
                    recipientId: opRecipientId,
                    recipientName: finalRecipientName
                });
                resetOpForm();
              }} className="p-8 space-y-6">
                 <div className="space-y-4">
                    <div className="relative" ref={searchContainerRef}>
                       <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1">Buscar Insumo (Nome ou EAN)</label>
                       <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                          <input 
                            type="text" 
                            value={opSearchQuery} 
                            onChange={e => { setOpSearchQuery(e.target.value); setIsSearchDropdownOpen(true); if(opItemId) setOpItemId(''); }} 
                            onFocus={() => setIsSearchDropdownOpen(true)}
                            className="w-full pl-9 pr-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none focus:border-blue-300 transition-all" 
                            placeholder="Digite o nome ou bipe o EAN..." 
                            autoComplete="off"
                          />
                       </div>

                       {isSearchDropdownOpen && predictiveResults.length > 0 && (
                         <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 z-[310] overflow-hidden animate-in fade-in slide-in-from-top-2">
                            {predictiveResults.map(i => (
                              <button key={i.id} type="button" onClick={() => handleSelectPredictiveItem(i)} className="w-full p-4 hover:bg-slate-50 text-left border-b border-slate-50 last:border-none flex items-center justify-between transition-colors">
                                 <div>
                                    <p className="font-black text-slate-800 text-sm">{i.name}</p>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase">{i.category} • EAN: {i.ean || 'N/A'}</p>
                                 </div>
                                 <div className="text-right">
                                    <p className="text-xs font-black text-slate-800">{i.quantity} {i.unit}</p>
                                    <p className="text-[8px] text-slate-400 uppercase">Saldo Atual</p>
                                 </div>
                              </button>
                            ))}
                         </div>
                       )}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                       <div className="flex bg-slate-50 p-1 rounded-xl border border-slate-100">
                          <button type="button" onClick={() => setOpType('Entrada')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${opType === 'Entrada' ? 'bg-white shadow-sm text-emerald-500' : 'text-slate-400'}`}>Entrada</button>
                          <button type="button" onClick={() => setOpType('Saída')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${opType === 'Saída' ? 'bg-white shadow-sm text-rose-500' : 'text-slate-400'}`}>Saída</button>
                       </div>
                       <input type="number" value={opQuantity || ''} onChange={e => setOpQuantity(parseInt(e.target.value) || 0)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none" placeholder="Quantidade" required />
                    </div>

                    {opType === 'Saída' && (
                        <div className="relative">
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1 flex items-center justify-between">
                                <span>Retirado por (Funcionário)</span>
                                <span className="flex items-center text-blue-500"><QrCode size={10} className="mr-1"/> Scan Ativo</span>
                            </label>
                            <div className="relative">
                                <Scan className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                                <input 
                                    ref={recipientInputRef}
                                    type="text" 
                                    value={opRecipientName} 
                                    onChange={handleScanRecipient}
                                    className="w-full pl-9 pr-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none focus:border-blue-300 transition-all bg-blue-50/50" 
                                    placeholder="Bipe o Crachá ou digite o nome..." 
                                    autoComplete="off"
                                />
                                {opRecipientName && (
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2">
                                        {opRecipientId ? (
                                            <CheckCircle2 size={18} className="text-emerald-500" />
                                        ) : (
                                            <span className="text-[9px] font-bold text-slate-400">Manual</span>
                                        )}
                                    </div>
                                )}
                            </div>
                            {/* Autocomplete for employees if typing manually */}
                            {opRecipientName && !opRecipientId && employeePredictive.length > 0 && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-lg border border-slate-100 z-[320] overflow-hidden">
                                    {employeePredictive.map(emp => (
                                        <button 
                                            key={emp.id} 
                                            type="button" 
                                            onClick={() => { setOpRecipientId(emp.id); setOpRecipientName(emp.name); }}
                                            className="w-full p-3 text-left hover:bg-slate-50 text-xs font-bold text-slate-700 border-b last:border-none"
                                        >
                                            {emp.name} <span className="text-slate-400">({emp.role})</span>
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    <input type="text" value={opReason} onChange={e => setOpReason(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none" placeholder="Motivo / Justificativa" />
                 </div>
                 <button type="submit" disabled={!opItemId} className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 disabled:opacity-50 disabled:grayscale" style={{ backgroundColor: theme.primary }}>Confirmar Movimentação</button>
              </form>
           </div>
        </div>
      )}

      {/* Modal FORNECEDOR */}
      {isAddingSupplier && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">Novo Fornecedor</h2>
                 <button onClick={() => setIsAddingSupplier(false)} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveSupplierSubmit} className="p-8 space-y-4">
                 <input type="text" value={supName} onChange={e => setSupName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Nome da Empresa" required />
                 <input type="text" value={supContact} onChange={e => setSupContact(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Contato (WhatsApp/Email)" />
                 <input type="text" value={supCategory} onChange={e => setSupCategory(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Categoria" />
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl" style={{ backgroundColor: theme.primary }}>Cadastrar Fornecedor</button>
              </form>
           </div>
        </div>
      )}

    </div>
  );
};

export default InventoryView;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { InventoryItem, InventoryOperation, HotelTheme, UserRole, Supplier, Employee, Sector } from '../types';
import { 
  Package, 
  Search, 
  Plus, 
  Trash2, 
  X,
  Edit2,
  CheckCircle2,
  ArrowUpRight,
  ArrowDownRight,
  History,
  ShoppingCart,
  PlusCircle,
  Calendar,
  User as UserIcon,
  Barcode,
  Truck,
  DollarSign,
  QrCode,
  Scan,
  Briefcase,
  Building2,
  ChevronLeft,
  AlertTriangle,
  ChevronDown,
  ChevronRight,
  Layers
} from 'lucide-react';

interface InventoryViewProps {
  inventory: InventoryItem[];
  history: InventoryOperation[];
  suppliers: Supplier[];
  employees?: Employee[];
  sectors?: Sector[];
  showSuppliersTab?: boolean;
  theme: HotelTheme;
  onSave: (item: InventoryItem) => void;
  onDelete: (id: string) => void;
  onOperation: (op: InventoryOperation) => void;
  onSaveSupplier: (supplier: Supplier) => void;
  onDeleteSupplier: (id: string) => void;
  onSaveSector?: (sector: Sector) => void;
  onDeleteSector?: (id: string) => void;
  role?: UserRole;
  currentUser?: string;
}

const InventoryView: React.FC<InventoryViewProps> = ({ 
  inventory, 
  history, 
  suppliers,
  employees = [],
  sectors = [],
  showSuppliersTab = true,
  theme, 
  onSave, 
  onDelete, 
  onOperation, 
  onSaveSupplier, 
  onDeleteSupplier,
  onSaveSector,
  onDeleteSector,
  role,
  currentUser 
}) => {
  const [selectedSectorId, setSelectedSectorId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'ESTOQUE' | 'OPERACAO' | 'SUGESTAO' | 'FORNECEDORES'>('ESTOQUE');

  // Modals state
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isAddingOp, setIsAddingOp] = useState(false);
  const [isAddingSupplier, setIsAddingSupplier] = useState(false);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [sectorToDelete, setSectorToDelete] = useState<Sector | null>(null);
  const [showEmptySectors, setShowEmptySectors] = useState(false);

  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);
  const [editingSupplier, setEditingSupplier] = useState<Supplier | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('Todos');

  // Form Item
  const [name, setName] = useState('');
  const [ean, setEan] = useState('');
  const [category, setCategory] = useState('Limpeza');
  const [initialQuantity, setInitialQuantity] = useState(0);
  const [unit, setUnit] = useState('Unidade');
  const [price, setPrice] = useState(0);
  const [supplierId, setSupplierId] = useState('');

  // Form Operation
  const [opSearchQuery, setOpSearchQuery] = useState('');
  const [opItemId, setOpItemId] = useState('');
  const [opType, setOpType] = useState<'Entrada' | 'Saída'>('Entrada');
  const [opQuantity, setOpQuantity] = useState(0);
  const [opReason, setOpReason] = useState('');
  const [opRecipientId, setOpRecipientId] = useState('');
  const [opRecipientName, setOpRecipientName] = useState('');

  // Form Sector
  const [sectorName, setSectorName] = useState('');

  const [isSearchDropdownOpen, setIsSearchDropdownOpen] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);
  const recipientInputRef = useRef<HTMLInputElement>(null);

  // Supplier form state
  const [supName, setSupName] = useState('');
  const [supContact, setSupContact] = useState('');
  const [supCategory, setSupCategory] = useState('');

  const categories = ['Limpeza', 'Rouparia', 'Amenidades', 'Escritório', 'Manutenção'];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setIsSearchDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const calculateOrderSuggestion = (item: InventoryItem) => {
    const thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
    const itemExits = history.filter(op => op.itemId === item.id && op.type === 'Saída' && op.timestamp > thirtyDaysAgo);
    const totalExited = itemExits.reduce((acc, curr) => acc + curr.quantity, 0);
    const mcd = totalExited / 30;
    const supplier = suppliers.find(s => s.id === item.supplierId);
    const isVMarketing = supplier?.name.toLowerCase().includes('v-marketing');
    const targetDays = isVMarketing ? 12 : 8;
    const targetStock = Math.ceil(mcd * targetDays);
    const suggestedQuantity = Math.max(0, targetStock - item.quantity);
    return { mcd, targetDays, targetStock, suggestedQuantity, isVMarketing, reason: isVMarketing ? "Ciclo de Quinta (V-Marketing): 12 dias" : "Ciclo de Quarta: 8 dias" };
  };

  // Pre-calculate counts to split sectors
  const sectorCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    inventory.forEach(i => {
        if(i.sectorId) counts[i.sectorId] = (counts[i.sectorId] || 0) + 1;
    });
    return counts;
  }, [inventory]);

  const activeSectors = useMemo(() => sectors.filter(s => (sectorCounts[s.id] || 0) > 0), [sectors, sectorCounts]);
  const emptySectors = useMemo(() => sectors.filter(s => (sectorCounts[s.id] || 0) === 0), [sectors, sectorCounts]);

  // Filter inventory by selected Sector
  const sectorInventory = useMemo(() => {
    return inventory.filter(i => i.sectorId === selectedSectorId);
  }, [inventory, selectedSectorId]);

  const enrichedInventory = useMemo(() => sectorInventory.map(item => {
    const suggestion = calculateOrderSuggestion(item);
    return { ...item, minQuantity: Math.ceil(suggestion.mcd * 7), suggestion, totalValue: item.quantity * (item.price || 0) };
  }), [sectorInventory, history, suppliers]);

  const globalTotalValue = useMemo(() => enrichedInventory.reduce((acc, curr) => acc + curr.totalValue, 0), [enrichedInventory]);

  const resetItemForm = () => {
    setName(''); setEan(''); setCategory('Limpeza'); setInitialQuantity(0); setUnit('Unidade'); setPrice(0); setSupplierId('');
    setEditingItem(null); setIsAddingItem(false);
  };

  const resetOpForm = () => {
    setIsAddingOp(false); setOpItemId(''); setOpSearchQuery(''); setOpQuantity(0); 
    setOpReason(''); setOpRecipientId(''); setOpRecipientName('');
  };

  const handleSaveItemSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId) return;
    onSave({ 
      id: editingItem?.id || Date.now().toString(), 
      ean, 
      name, 
      category, 
      quantity: initialQuantity, 
      unit, 
      price, 
      supplierId, 
      sectorId: selectedSectorId, // Bind to current sector
      minQuantity: 0, 
      lastUpdate: Date.now() 
    });
    resetItemForm();
  };

  const handleSaveSupplierSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSaveSupplier({ id: editingSupplier?.id || Date.now().toString(), name: supName, contact: supContact, category: supCategory });
    setSupName(''); setSupContact(''); setSupCategory(''); setIsAddingSupplier(false); setEditingSupplier(null);
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSaveSector) {
      onSaveSector({ id: Date.now().toString(), name: sectorName, standardUniform: [] });
      setSectorName('');
      setIsAddingSector(false);
    }
  };

  const filteredItems = useMemo(() => enrichedInventory.filter(i => 
    (categoryFilter === 'Todos' || i.category === categoryFilter) &&
    (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || (i.ean && i.ean.includes(searchTerm)))
  ), [enrichedInventory, categoryFilter, searchTerm]);

  const predictiveResults = useMemo(() => {
    if (!opSearchQuery || opSearchQuery.length < 2) return [];
    return sectorInventory.filter(i => 
      i.name.toLowerCase().includes(opSearchQuery.toLowerCase()) || 
      (i.ean && i.ean.includes(opSearchQuery))
    ).slice(0, 5);
  }, [sectorInventory, opSearchQuery]);

  const suggestedOrders = useMemo(() => enrichedInventory.filter(i => i.suggestion.suggestedQuantity > 0), [enrichedInventory]);

  const employeePredictive = useMemo(() => {
    if (!opRecipientName || opRecipientName.length < 2) return [];
    return employees.filter(e => e.name.toLowerCase().includes(opRecipientName.toLowerCase())).slice(0, 5);
  }, [employees, opRecipientName]);

  const handleSelectPredictiveItem = (item: InventoryItem) => {
    setOpItemId(item.id);
    setOpSearchQuery(item.name);
    setIsSearchDropdownOpen(false);
  };

  const handleScanRecipient = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setOpRecipientName(val);

      const exactMatch = employees.find(emp => emp.id === val || emp.name.toLowerCase() === val.toLowerCase());
      if(exactMatch) {
          setOpRecipientId(exactMatch.id);
          setOpRecipientName(exactMatch.name);
      } else {
          setOpRecipientId('');
      }
  };

  // --- SECTOR SELECTION VIEW ---
  if (!selectedSectorId) {
    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Controle de Estoque</p>
          <div className="flex gap-2">
            <button 
              onClick={() => setIsAddingSector(true)} 
              className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" 
              style={{ backgroundColor: theme.primary }}
            >
              <Plus size={18} /> <span>Novo Setor</span>
            </button>
          </div>
        </div>

        {/* GRUPO 1: SETORES ATIVOS (COM PRODUTOS) */}
        {activeSectors.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {activeSectors.map((sec) => (
              <div key={sec.id} className="relative group">
                {/* Botão de Excluir Setor - Apenas Gestores */}
                {onDeleteSector && role !== 'FUNCIONARIO' && (
                  <button 
                    onClick={(e) => { 
                      e.stopPropagation(); 
                      setSectorToDelete(sec);
                    }}
                    className="absolute top-4 right-4 z-10 p-2 bg-white/90 rounded-full text-slate-300 hover:text-rose-500 hover:bg-white shadow-sm opacity-0 group-hover:opacity-100 transition-all"
                    title="Excluir Setor"
                  >
                    <Trash2 size={16} />
                  </button>
                )}

                <button onClick={() => setSelectedSectorId(sec.id)} className="w-full bg-white h-48 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all border border-slate-50 flex flex-col items-center justify-center overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1.5" style={{ backgroundColor: theme.primary }}></div>
                  <div className="p-5 rounded-2xl mb-3 bg-slate-50 text-slate-400 group-hover:scale-110 transition-transform">
                    <Package size={32} />
                  </div>
                  <h3 className="text-xl font-black text-slate-800">{sec.name}</h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase mt-1">
                    {sectorCounts[sec.id] || 0} Itens em Estoque
                  </p>
                </button>
              </div>
            ))}
          </div>
        ) : (
           <div className="text-center py-10">
              <p className="text-slate-400 font-bold italic">Nenhum setor com estoque ativo. Comece adicionando um item abaixo.</p>
           </div>
        )}

        {/* GRUPO 2: SETORES VAZIOS (ESCONDIDOS/COLAPSÁVEIS) */}
        {emptySectors.length > 0 && (
          <div className="mt-8 border-t border-slate-100 pt-8">
            <button 
              onClick={() => setShowEmptySectors(!showEmptySectors)} 
              className="flex items-center space-x-2 text-slate-500 font-black text-xs uppercase tracking-widest hover:text-slate-800 transition-colors mb-4"
            >
              {showEmptySectors ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
              <span>Iniciar Estoque em Novos Setores ({emptySectors.length})</span>
            </button>

            {showEmptySectors && (
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 animate-in slide-in-from-top-2">
                {emptySectors.map((sec) => (
                  <div key={sec.id} className="relative group">
                    {/* Botão de Excluir Setor Vazio */}
                    {onDeleteSector && role !== 'FUNCIONARIO' && (
                      <button 
                        onClick={(e) => { 
                          e.stopPropagation(); 
                          setSectorToDelete(sec);
                        }}
                        className="absolute top-2 right-2 z-10 p-1.5 bg-white rounded-full text-slate-300 hover:text-rose-500 hover:bg-rose-50 shadow-sm opacity-0 group-hover:opacity-100 transition-all"
                      >
                        <Trash2 size={12} />
                      </button>
                    )}

                    <button 
                      onClick={() => setSelectedSectorId(sec.id)} 
                      className="w-full bg-slate-50 hover:bg-white border-2 border-dashed border-slate-200 hover:border-blue-300 rounded-2xl p-4 flex flex-col items-center justify-center transition-all h-32 group-hover:shadow-md"
                    >
                      <PlusCircle size={24} className="text-slate-300 mb-2 group-hover:text-blue-500 transition-colors"/>
                      <span className="font-bold text-slate-600 text-sm text-center leading-tight">{sec.name}</span>
                      <span className="text-[8px] font-black text-slate-400 uppercase mt-1">Adicionar Item</span>
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {isAddingSector && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
                <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
                   <h3 className="font-black text-slate-800">Novo Setor de Estoque</h3>
                   <button onClick={() => setIsAddingSector(false)}><X size={24} className="text-slate-300"/></button>
                </div>
                <form onSubmit={handleSaveSectorSubmit} className="p-6 space-y-4">
                   <input 
                     type="text" 
                     value={sectorName} 
                     onChange={e => setSectorName(e.target.value)} 
                     placeholder="Nome do Setor (Ex: Manutenção)" 
                     className="w-full px-4 py-3 rounded-xl border-2 font-bold text-slate-800 outline-none focus:border-blue-400" 
                     required 
                   />
                   <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black text-xs uppercase shadow-lg">Criar Setor</button>
                </form>
             </div>
          </div>
        )}

        {/* Modal de Confirmação de Exclusão de Setor */}
        {sectorToDelete && (
          <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-sm rounded-[2rem] shadow-2xl p-6 animate-in zoom-in-95 duration-200 border border-white/20">
              <div className="flex flex-col items-center text-center space-y-4">
                <div className="p-4 bg-red-50 text-red-500 rounded-full shadow-inner">
                  <Trash2 size={32} />
                </div>
                <div>
                  <h3 className="text-lg font-black text-slate-800">Excluir Setor?</h3>
                  <p className="text-xs text-slate-500 font-bold mt-2 leading-relaxed">
                    Você está prestes a remover o setor <br/><span className="text-slate-800 text-sm">"{sectorToDelete.name}"</span>.
                  </p>
                  <p className="text-[10px] text-slate-400 mt-2 font-medium bg-slate-50 p-2 rounded-lg border border-slate-100">
                    <AlertTriangle size={12} className="inline mr-1 mb-0.5"/>
                    Os itens vinculados não serão apagados, mas ficarão sem setor definido.
                  </p>
                </div>
                <div className="flex gap-3 w-full pt-2">
                  <button 
                    onClick={() => setSectorToDelete(null)}
                    className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-black text-xs uppercase hover:bg-slate-200 transition-colors"
                  >
                    Cancelar
                  </button>
                  <button 
                    onClick={() => {
                      if (onDeleteSector) onDeleteSector(sectorToDelete.id);
                      setSectorToDelete(null);
                    }}
                    className="flex-1 py-3 bg-red-500 text-white rounded-xl font-black text-xs uppercase shadow-lg hover:bg-red-600 transition-colors"
                  >
                    Confirmar
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- INVENTORY DETAIL VIEW (FOR SELECTED SECTOR) ---
  const currentSector = sectors.find(s => s.id === selectedSectorId);

  return (
    <div className="space-y-6 animate-in slide-in-from-right-4 duration-500 pb-20">

      {/* Header com Navegação e Valor Total */}
      <div className="flex flex-col space-y-4">
        <button 
           onClick={() => setSelectedSectorId(null)} 
           className="self-start flex items-center text-slate-400 hover:text-slate-800 transition-colors font-bold text-xs"
        >
           <ChevronLeft size={16} className="mr-1"/> Voltar para Setores
        </button>

        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
           <div className="flex items-center space-x-4">
              <div className="p-4 bg-slate-900 text-white rounded-2xl"><Package size={24}/></div>
              <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Estoque: {currentSector?.name}</p>
                 <h3 className="text-2xl font-black text-slate-800">R$ {globalTotalValue.toLocaleString('pt-BR')}</h3>
              </div>
           </div>
           <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100 shadow-sm w-full md:w-auto overflow-x-auto">
              {[
                { id: 'ESTOQUE', label: 'Itens', icon: Package },
                { id: 'OPERACAO', label: 'Movimentos', icon: History },
                { id: 'SUGESTAO', label: 'Pedidos', icon: ShoppingCart },
                ...(showSuppliersTab ? [{ id: 'FORNECEDORES', label: 'Fornecedores', icon: Truck }] : [])
              ].map(tab => (
                <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 flex items-center justify-center space-x-2 py-2.5 px-4 rounded-xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                  <tab.icon size={14} /> <span className="hidden sm:inline">{tab.label}</span>
                </button>
              ))}
           </div>
        </div>
      </div>

      {activeTab === 'ESTOQUE' && (
        <div className="space-y-6 animate-in slide-in-from-bottom-2">
          <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
            <div className="flex gap-3 w-full md:w-auto">
              <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                <input type="text" placeholder="Buscar por nome ou EAN..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 outline-none text-sm font-bold bg-white shadow-inner" />
              </div>
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="px-4 py-3 rounded-xl border border-slate-100 outline-none bg-white text-sm font-bold shadow-inner">
                <option value="Todos">Categorias</option>
                {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div className="flex gap-2 w-full md:w-auto">
               <button onClick={() => setIsAddingOp(true)} className="flex-1 md:w-auto border-2 border-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 bg-white transition-all active:scale-95">
                 <PlusCircle size={18} /> <span>Movimentação</span>
               </button>
               {role !== 'FUNCIONARIO' && (
                 <button onClick={() => setIsAddingItem(true)} className="flex-1 md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95" style={{ backgroundColor: theme.primary }}>
                   <Plus size={18} /> <span>Novo Item</span>
                 </button>
               )}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="bg-slate-50 border-b border-slate-100">
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Insumo</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Saldo</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Consumo Médio</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">R$ Unit</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">R$ Total</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {filteredItems.map(item => {
                    const isLow = item.quantity <= item.minQuantity;
                    return (
                      <tr key={item.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-8 py-5">
                          <p className="font-black text-slate-800 leading-tight">{item.name}</p>
                          <div className="flex items-center space-x-2 mt-1">
                            {item.ean && <span className="text-[8px] text-blue-500 font-black uppercase flex items-center bg-blue-50 px-1.5 py-0.5 rounded"><Barcode size={8} className="mr-1" /> {item.ean}</span>}
                            <span className="text-[8px] text-slate-400 font-bold uppercase">{item.category} • {item.unit}</span>
                          </div>
                        </td>
                        <td className="px-8 py-5 text-center">
                          <span className={`text-lg font-black ${isLow ? 'text-rose-500' : 'text-slate-800'}`}>{item.quantity}</span>
                        </td>
                        <td className="px-8 py-5 text-center text-xs font-bold text-slate-400">{item.suggestion.mcd.toFixed(2)}/dia</td>
                        <td className="px-8 py-5 text-center text-xs font-bold text-slate-600">R$ {(item.price || 0).toLocaleString('pt-BR')}</td>
                        <td className="px-8 py-5 text-center text-sm font-black text-slate-900">R$ {item.totalValue.toLocaleString('pt-BR')}</td>
                        <td className="px-8 py-5 text-right">
                          <button onClick={() => { setEditingItem(item); setName(item.name); setEan(item.ean || ''); setCategory(item.category); setInitialQuantity(item.quantity); setUnit(item.unit); setPrice(item.price || 0); setSupplierId(item.supplierId || ''); setIsAddingItem(true); }} className="p-2 text-slate-300 hover:text-blue-500"><Edit2 size={18}/></button>
                          {role !== 'FUNCIONARIO' && <button onClick={() => onDelete(item.id)} className="p-2 text-slate-300 hover:text-rose-500 ml-2"><Trash2 size={18}/></button>}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            {filteredItems.length === 0 && (
                <div className="py-20 text-center text-slate-300 italic font-bold">
                    Nenhum item encontrado neste setor.
                </div>
            )}
          </div>
        </div>
      )}

      {/* ... (OPERACAO, SUGESTAO, FORNECEDORES tabs remain largely the same) ... */}
       {activeTab === 'OPERACAO' && (
        <div className="space-y-6 animate-in slide-in-from-right-4">
           <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
              <div className="flex items-center justify-between mb-8">
                 <h3 className="text-xl font-black text-slate-800 flex items-center"><History size={24} className="mr-3 text-slate-400"/> Histórico de Movimentações</h3>
                 <button onClick={() => setIsAddingOp(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg">Nova Operação</button>
              </div>
              <div className="space-y-4">
                 {history.length === 0 ? (
                    <p className="text-center py-20 text-slate-300 italic font-bold">Nenhuma movimentação registrada.</p>
                 ) : (
                    history.map(op => (
                       <div key={op.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <div className="flex items-center space-x-4">
                             <div className={`p-3 rounded-xl ${op.type === 'Entrada' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                                {op.type === 'Entrada' ? <ArrowUpRight size={20}/> : <ArrowDownRight size={20}/>}
                             </div>
                             <div>
                                <p className="font-black text-slate-800">{op.itemName}</p>
                                <div className="flex flex-col md:flex-row md:items-center text-[10px] text-slate-400 font-bold uppercase gap-2">
                                   <span className="flex items-center"><UserIcon size={10} className="mr-1"/> {op.user}</span>
                                   <span className="flex items-center"><Calendar size={10} className="mr-1"/> {new Date(op.timestamp).toLocaleString()}</span>
                                   {op.recipientName && (
                                       <span className="flex items-center text-blue-500"><Scan size={10} className="mr-1"/> Retirado por: {op.recipientName}</span>
                                   )}
                                </div>
                             </div>
                          </div>
                          <div className="text-right">
                             <p className={`text-lg font-black ${op.type === 'Entrada' ? 'text-emerald-500' : 'text-rose-500'}`}>
                                {op.type === 'Entrada' ? '+' : '-'}{op.quantity}
                             </p>
                             {op.reason && <p className="text-[9px] text-slate-400 font-medium">{op.reason}</p>}
                          </div>
                       </div>
                    ))
                 )}
              </div>
           </div>
        </div>
      )}

      {/* Modal FORNECEDOR */}
      {isAddingSupplier && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">Novo Fornecedor</h2>
                 <button onClick={() => setIsAddingSupplier(false)} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveSupplierSubmit} className="p-8 space-y-4">
                 <input type="text" value={supName} onChange={e => setSupName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Nome da Empresa" required />
                 <input type="text" value={supContact} onChange={e => setSupContact(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Contato (WhatsApp/Email)" />
                 <input type="text" value={supCategory} onChange={e => setSupCategory(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Categoria" />
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl" style={{ backgroundColor: theme.primary }}>Cadastrar Fornecedor</button>
              </form>
           </div>
        </div>
      )}

    </div>
  );
};

export default InventoryView;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { InventoryItem, InventoryOperation, HotelTheme, UserRole, Supplier, Employee, Sector } from '../types';
import { 
  Package, 
  Search, 
  Plus, 
  Trash2, 
  X,
  Edit2,
  CheckCircle2,
  ArrowUpRight,
  ArrowDownRight,
  History,
  ShoppingCart,
  PlusCircle,
  Calendar,
  User as UserIcon,
  Barcode,
  Truck,
  DollarSign,
  QrCode,
  Scan,
  Briefcase,
  Building2,
  ChevronLeft,
  AlertTriangle,
  ChevronDown,
  ChevronRight,
  Layers
} from 'lucide-react';

interface InventoryViewProps {
  inventory: InventoryItem[];
  history: InventoryOperation[];
  suppliers: Supplier[];
  employees?: Employee[];
  sectors?: Sector[];
  showSuppliersTab?: boolean;
  theme: HotelTheme;
  onSave: (item: InventoryItem) => void;
  onDelete: (id: string) => void;
  onOperation: (op: InventoryOperation) => void;
  onSaveSupplier: (supplier: Supplier) => void;
  onDeleteSupplier: (id: string) => void;
  onSaveSector?: (sector: Sector) => void;
  onDeleteSector?: (id: string) => void;
  role?: UserRole;
  currentUser?: string;
}

const InventoryView: React.FC<InventoryViewProps> = ({ 
  inventory, 
  history, 
  suppliers,
  employees = [],
  sectors = [],
  showSuppliersTab = true,
  theme, 
  onSave, 
  onDelete, 
  onOperation, 
  onSaveSupplier, 
  onDeleteSupplier,
  onSaveSector,
  onDeleteSector,
  role,
  currentUser 
}) => {
  const [selectedSectorId, setSelectedSectorId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'ESTOQUE' | 'OPERACAO' | 'SUGESTAO' | 'FORNECEDORES'>('ESTOQUE');

  // Modals state
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isAddingOp, setIsAddingOp] = useState(false);
  const [isAddingSupplier, setIsAddingSupplier] = useState(false);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [sectorToDelete, setSectorToDelete] = useState<Sector | null>(null);
  const [showEmptySectors, setShowEmptySectors] = useState(false);

  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);
  const [editingSupplier, setEditingSupplier] = useState<Supplier | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('Todos');

  // Form Item
  const [name, setName] = useState('');
  const [ean, setEan] = useState('');
  const [category, setCategory] = useState('Limpeza');
  const [initialQuantity, setInitialQuantity] = useState(0);
  const [unit, setUnit] = useState('Unidade');
  const [price, setPrice] = useState(0);
  const [supplierId, setSupplierId] = useState('');

  // Form Operation
  const [opSearchQuery, setOpSearchQuery] = useState('');
  const [opItemId, setOpItemId] = useState('');
  const [opType, setOpType] = useState<'Entrada' | 'Saída'>('Entrada');
  const [opQuantity, setOpQuantity] = useState(0);
  const [opReason, setOpReason] = useState('');
  const [opRecipientId, setOpRecipientId] = useState('');
  const [opRecipientName, setOpRecipientName] = useState('');

  // Form Sector
  const [sectorName, setSectorName] = useState('');

  const [isSearchDropdownOpen, setIsSearchDropdownOpen] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);
  const recipientInputRef = useRef<HTMLInputElement>(null);

  // Supplier form state
  const [supName, setSupName] = useState('');
  const [supContact, setSupContact] = useState('');
  const [supCategory, setSupCategory] = useState('');

  const categories = ['Limpeza', 'Rouparia', 'Amenidades', 'Escritório', 'Manutenção'];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setIsSearchDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const calculateOrderSuggestion = (item: InventoryItem) => {
    const thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
    const itemExits = history.filter(op => op.itemId === item.id && op.type === 'Saída' && op.timestamp > thirtyDaysAgo);
    const totalExited = itemExits.reduce((acc, curr) => acc + curr.quantity, 0);
    const mcd = totalExited / 30;
    const supplier = suppliers.find(s => s.id === item.supplierId);
    const isVMarketing = supplier?.name.toLowerCase().includes('v-marketing');
    const targetDays = isVMarketing ? 12 : 8;
    const targetStock = Math.ceil(mcd * targetDays);
    const suggestedQuantity = Math.max(0, targetStock - item.quantity);
    return { mcd, targetDays, targetStock, suggestedQuantity, isVMarketing, reason: isVMarketing ? "Ciclo de Quinta (V-Marketing): 12 dias" : "Ciclo de Quarta: 8 dias" };
  };

  // Pre-calculate counts to split sectors
  const sectorCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    inventory.forEach(i => {
        if(i.sectorId) counts[i.sectorId] = (counts[i.sectorId] || 0) + 1;
    });
    return counts;
  }, [inventory]);

  const activeSectors = useMemo(() => sectors.filter(s => (sectorCounts[s.id] || 0) > 0), [sectors, sectorCounts]);
  const emptySectors = useMemo(() => sectors.filter(s => (sectorCounts[s.id] || 0) === 0), [sectors, sectorCounts]);

  // Filter inventory by selected Sector
  const sectorInventory = useMemo(() => {
    return inventory.filter(i => i.sectorId === selectedSectorId);
  }, [inventory, selectedSectorId]);

  const enrichedInventory = useMemo(() => sectorInventory.map(item => {
    const suggestion = calculateOrderSuggestion(item);
    return { ...item, minQuantity: Math.ceil(suggestion.mcd * 7), suggestion, totalValue: item.quantity * (item.price || 0) };
  }), [sectorInventory, history, suppliers]);

  const globalTotalValue = useMemo(() => enrichedInventory.reduce((acc, curr) => acc + curr.totalValue, 0), [enrichedInventory]);

  const resetItemForm = () => {
    setName(''); setEan(''); setCategory('Limpeza'); setInitialQuantity(0); setUnit('Unidade'); setPrice(0); setSupplierId('');
    setEditingItem(null); setIsAddingItem(false);
  };

  const resetOpForm = () => {
    setIsAddingOp(false); setOpItemId(''); setOpSearchQuery(''); setOpQuantity(0); 
    setOpReason(''); setOpRecipientId(''); setOpRecipientName('');
  };

  const handleSaveItemSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId) return;
    onSave({ 
      id: editingItem?.id || Date.now().toString(), 
      ean, 
      name, 
      category, 
      quantity: initialQuantity, 
      unit, 
      price, 
      supplierId, 
      sectorId: selectedSectorId, // Bind to current sector
      minQuantity: 0, 
      lastUpdate: Date.now() 
    });
    resetItemForm();
  };

  const handleSaveSupplierSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSaveSupplier({ id: editingSupplier?.id || Date.now().toString(), name: supName, contact: supContact, category: supCategory });
    setSupName(''); setSupContact(''); setSupCategory(''); setIsAddingSupplier(false); setEditingSupplier(null);
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSaveSector) {
      onSaveSector({ id: Date.now().toString(), name: sectorName, standardUniform: [] });
      setSectorName('');
      setIsAddingSector(false);
    }
  };

  const filteredItems = useMemo(() => enrichedInventory.filter(i => 
    (categoryFilter === 'Todos' || i.category === categoryFilter) &&
    (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || (i.ean && i.ean.includes(searchTerm)))
  ), [enrichedInventory, categoryFilter, searchTerm]);

  const predictiveResults = useMemo(() => {
    if (!opSearchQuery || opSearchQuery.length < 2) return [];
    return sectorInventory.filter(i => 
      i.name.toLowerCase().includes(opSearchQuery.toLowerCase()) || 
      (i.ean && i.ean.includes(opSearchQuery))
    ).slice(0, 5);
  }, [sectorInventory, opSearchQuery]);

  const suggestedOrders = useMemo(() => enrichedInventory.filter(i => i.suggestion.suggestedQuantity > 0), [enrichedInventory]);

  const employeePredictive = useMemo(() => {
    if (!opRecipientName || opRecipientName.length < 2) return [];
    return employees.filter(e => e.name.toLowerCase().includes(opRecipientName.toLowerCase())).slice(0, 5);
  }, [employees, opRecipientName]);

  const handleSelectPredictiveItem = (item: InventoryItem) => {
    setOpItemId(item.id);
    setOpSearchQuery(item.name);
    setIsSearchDropdownOpen(false);
  };

  const handleScanRecipient = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setOpRecipientName(val);

      const exactMatch = employees.find(emp => emp.id === val || emp.name.toLowerCase() === val.toLowerCase());
      if(exactMatch) {
          setOpRecipientId(exactMatch.id);
          setOpRecipientName(exactMatch.name);
      } else {
          setOpRecipientId('');
      }
  };

  // --- SECTOR SELECTION VIEW ---
  if (!selectedSectorId) {
    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Controle de Estoque</p>
          <div className="flex gap-2">
            <button 
              onClick={() => setIsAddingSector(true)} 
              className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" 
              style={{ backgroundColor: theme.primary }}
            >
              <Plus size={18} /> <span>Novo Setor</span>
            </button>
          </div>
        </div>

        {/* GRUPO 1: SETORES ATIVOS (COM PRODUTOS) */}
        {activeSectors.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {activeSectors.map((sec) => (
              <div key={sec.id} className="relative group">
                {/* Botão de Excluir Setor - Apenas Gestores */}
                {onDeleteSector && role !== 'FUNCIONARIO' && (
                  <button 
                    onClick={(e) => { 
                      e.stopPropagation(); 
                      setSectorToDelete(sec);
                    }}
                    className="absolute top-4 right-4 z-10 p-2 bg-white/90 rounded-full text-slate-300 hover:text-rose-500 hover:bg-white shadow-sm opacity-0 group-hover:opacity-100 transition-all"
                    title="Excluir Setor"
                  >
                    <Trash2 size={16} />
                  </button>
                )}

                <button onClick={() => setSelectedSectorId(sec.id)} className="w-full bg-white h-48 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all border border-slate-50 flex flex-col items-center justify-center overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1.5" style={{ backgroundColor: theme.primary }}></div>
                  <div className="p-5 rounded-2xl mb-3 bg-slate-50 text-slate-400 group-hover:scale-110 transition-transform">
                    <Package size={32} />
                  </div>
                  <h3 className="text-xl font-black text-slate-800">{sec.name}</h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase mt-1">
                    {sectorCounts[sec.id] || 0} Itens em Estoque
                  </p>
                </button>
              </div>
            ))}
          </div>
        ) : (
           <div className="text-center py-10">
              <p className="text-slate-400 font-bold italic">Nenhum setor com estoque ativo. Comece adicionando um item abaixo.</p>
           </div>
        )}

        {/* GRUPO 2: SETORES VAZIOS (ESCONDIDOS/COLAPSÁVEIS) */}
        {emptySectors.length > 0 && (
          <div className="mt-8 border-t border-slate-100 pt-8">
            <button 
              onClick={() => setShowEmptySectors(!showEmptySectors)} 
              className="flex items-center space-x-2 text-slate-500 font-black text-xs uppercase tracking-widest hover:text-slate-800 transition-colors mb-4"
            >
              {showEmptySectors ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
              <span>Iniciar Estoque em Novos Setores ({emptySectors.length})</span>
            </button>

            {showEmptySectors && (
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 animate-in slide-in-from-top-2">
                {emptySectors.map((sec) => (
                  <div key={sec.id} className="relative group">
                    {/* Botão de Excluir Setor Vazio */}
                    {onDeleteSector && role !== 'FUNCIONARIO' && (
                      <button 
                        onClick={(e) => { 
                          e.stopPropagation(); 
                          setSectorToDelete(sec);
                        }}
                        className="absolute top-2 right-2 z-10 p-1.5 bg-white rounded-full text-slate-300 hover:text-rose-500 hover:bg-rose-50 shadow-sm opacity-0 group-hover:opacity-100 transition-all"
                      >
                        <Trash2 size={12} />
                      </button>
                    )}

                    <button 
                      onClick={() => { 
                         // CORREÇÃO: Abre o setor E o modal de adição de item ao mesmo tempo
                         setSelectedSectorId(sec.id);
                         setIsAddingItem(true);
                      }} 
                      className="w-full bg-slate-50 hover:bg-white border-2 border-dashed border-slate-200 hover:border-blue-300 rounded-2xl p-4 flex flex-col items-center justify-center transition-all h-32 group-hover:shadow-md"
                    >
                      <PlusCircle size={24} className="text-slate-300 mb-2 group-hover:text-blue-500 transition-colors"/>
                      <span className="font-bold text-slate-600 text-sm text-center leading-tight">{sec.name}</span>
                      <span className="text-[8px] font-black text-slate-400 uppercase mt-1">Adicionar Item</span>
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {isAddingSector && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
                <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
                   <h3 className="font-black text-slate-800">Novo Setor de Estoque</h3>
                   <button onClick={() => setIsAddingSector(false)}><X size={24} className="text-slate-300"/></button>
                </div>
                <form onSubmit={handleSaveSectorSubmit} className="p-6 space-y-4">
                   <input 
                     type="text" 
                     value={sectorName} 
                     onChange={e => setSectorName(e.target.value)} 
                     placeholder="Nome do Setor (Ex: Manutenção)" 
                     className="w-full px-4 py-3 rounded-xl border-2 font-bold text-slate-800 outline-none focus:border-blue-400" 
                     required 
                   />
                   <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black text-xs uppercase shadow-lg">Criar Setor</button>
                </form>
             </div>
          </div>
        )}

        {/* Modal de Confirmação de Exclusão de Setor */}
        {sectorToDelete && (
          <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-sm rounded-[2rem] shadow-2xl p-6 animate-in zoom-in-95 duration-200 border border-white/20">
              <div className="flex flex-col items-center text-center space-y-4">
                <div className="p-4 bg-red-50 text-red-500 rounded-full shadow-inner">
                  <Trash2 size={32} />
                </div>
                <div>
                  <h3 className="text-lg font-black text-slate-800">Excluir Setor?</h3>
                  <p className="text-xs text-slate-500 font-bold mt-2 leading-relaxed">
                    Você está prestes a remover o setor <br/><span className="text-slate-800 text-sm">"{sectorToDelete.name}"</span>.
                  </p>
                  <p className="text-[10px] text-slate-400 mt-2 font-medium bg-slate-50 p-2 rounded-lg border border-slate-100">
                    <AlertTriangle size={12} className="inline mr-1 mb-0.5"/>
                    Os itens vinculados não serão apagados, mas ficarão sem setor definido.
                  </p>
                </div>
                <div className="flex gap-3 w-full pt-2">
                  <button 
                    onClick={() => setSectorToDelete(null)}
                    className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-black text-xs uppercase hover:bg-slate-200 transition-colors"
                  >
                    Cancelar
                  </button>
                  <button 
                    onClick={() => {
                      if (onDeleteSector) onDeleteSector(sectorToDelete.id);
                      setSectorToDelete(null);
                    }}
                    className="flex-1 py-3 bg-red-500 text-white rounded-xl font-black text-xs uppercase shadow-lg hover:bg-red-600 transition-colors"
                  >
                    Confirmar
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- INVENTORY DETAIL VIEW (FOR SELECTED SECTOR) ---
  const currentSector = sectors.find(s => s.id === selectedSectorId);

  return (
    <div className="space-y-6 animate-in slide-in-from-right-4 duration-500 pb-20">

      {/* Header com Navegação e Valor Total */}
      <div className="flex flex-col space-y-4">
        <button 
           onClick={() => setSelectedSectorId(null)} 
           className="self-start flex items-center text-slate-400 hover:text-slate-800 transition-colors font-bold text-xs"
        >
           <ChevronLeft size={16} className="mr-1"/> Voltar para Setores
        </button>

        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
           <div className="flex items-center space-x-4">
              <div className="p-4 bg-slate-900 text-white rounded-2xl"><Package size={24}/></div>
              <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Estoque: {currentSector?.name}</p>
                 <h3 className="text-2xl font-black text-slate-800">R$ {globalTotalValue.toLocaleString('pt-BR')}</h3>
              </div>
           </div>
           <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100 shadow-sm w-full md:w-auto overflow-x-auto">
              {[
                { id: 'ESTOQUE', label: 'Itens', icon: Package },
                { id: 'OPERACAO', label: 'Movimentos', icon: History },
                { id: 'SUGESTAO', label: 'Pedidos', icon: ShoppingCart },
                ...(showSuppliersTab ? [{ id: 'FORNECEDORES', label: 'Fornecedores', icon: Truck }] : [])
              ].map(tab => (
                <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 flex items-center justify-center space-x-2 py-2.5 px-4 rounded-xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                  <tab.icon size={14} /> <span className="hidden sm:inline">{tab.label}</span>
                </button>
              ))}
           </div>
        </div>
      </div>

      {activeTab === 'ESTOQUE' && (
        <div className="space-y-6 animate-in slide-in-from-bottom-2">
          <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
            <div className="flex gap-3 w-full md:w-auto">
              <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                <input type="text" placeholder="Buscar por nome ou EAN..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 outline-none text-sm font-bold bg-white shadow-inner" />
              </div>
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="px-4 py-3 rounded-xl border border-slate-100 outline-none bg-white text-sm font-bold shadow-inner">
                <option value="Todos">Categorias</option>
                {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div className="flex gap-2 w-full md:w-auto">
               <button onClick={() => setIsAddingOp(true)} className="flex-1 md:w-auto border-2 border-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 bg-white transition-all active:scale-95">
                 <PlusCircle size={18} /> <span>Movimentação</span>
               </button>
               {role !== 'FUNCIONARIO' && (
                 <button onClick={() => setIsAddingItem(true)} className="flex-1 md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95" style={{ backgroundColor: theme.primary }}>
                   <Plus size={18} /> <span>Novo Item</span>
                 </button>
               )}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="bg-slate-50 border-b border-slate-100">
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Insumo</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Saldo</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Consumo Médio</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">R$ Unit</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">R$ Total</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {filteredItems.map(item => {
                    const isLow = item.quantity <= item.minQuantity;
                    return (
                      <tr key={item.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-8 py-5">
                          <p className="font-black text-slate-800 leading-tight">{item.name}</p>
                          <div className="flex items-center space-x-2 mt-1">
                            {item.ean && <span className="text-[8px] text-blue-500 font-black uppercase flex items-center bg-blue-50 px-1.5 py-0.5 rounded"><Barcode size={8} className="mr-1" /> {item.ean}</span>}
                            <span className="text-[8px] text-slate-400 font-bold uppercase">{item.category} • {item.unit}</span>
                          </div>
                        </td>
                        <td className="px-8 py-5 text-center">
                          <span className={`text-lg font-black ${isLow ? 'text-rose-500' : 'text-slate-800'}`}>{item.quantity}</span>
                        </td>
                        <td className="px-8 py-5 text-center text-xs font-bold text-slate-400">{item.suggestion.mcd.toFixed(2)}/dia</td>
                        <td className="px-8 py-5 text-center text-xs font-bold text-slate-600">R$ {(item.price || 0).toLocaleString('pt-BR')}</td>
                        <td className="px-8 py-5 text-center text-sm font-black text-slate-900">R$ {item.totalValue.toLocaleString('pt-BR')}</td>
                        <td className="px-8 py-5 text-right">
                          <button onClick={() => { setEditingItem(item); setName(item.name); setEan(item.ean || ''); setCategory(item.category); setInitialQuantity(item.quantity); setUnit(item.unit); setPrice(item.price || 0); setSupplierId(item.supplierId || ''); setIsAddingItem(true); }} className="p-2 text-slate-300 hover:text-blue-500"><Edit2 size={18}/></button>
                          {role !== 'FUNCIONARIO' && <button onClick={() => onDelete(item.id)} className="p-2 text-slate-300 hover:text-rose-500 ml-2"><Trash2 size={18}/></button>}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            {filteredItems.length === 0 && (
                <div className="py-20 text-center text-slate-300 italic font-bold">
                    Nenhum item encontrado neste setor.
                </div>
            )}
          </div>
        </div>
      )}

      {/* ... (OPERACAO, SUGESTAO, FORNECEDORES tabs remain largely the same) ... */}
       {activeTab === 'OPERACAO' && (
        <div className="space-y-6 animate-in slide-in-from-right-4">
           <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
              <div className="flex items-center justify-between mb-8">
                 <h3 className="text-xl font-black text-slate-800 flex items-center"><History size={24} className="mr-3 text-slate-400"/> Histórico de Movimentações</h3>
                 <button onClick={() => setIsAddingOp(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg">Nova Operação</button>
              </div>
              <div className="space-y-4">
                 {history.length === 0 ? (
                    <p className="text-center py-20 text-slate-300 italic font-bold">Nenhuma movimentação registrada.</p>
                 ) : (
                    history.map(op => (
                       <div key={op.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <div className="flex items-center space-x-4">
                             <div className={`p-3 rounded-xl ${op.type === 'Entrada' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                                {op.type === 'Entrada' ? <ArrowUpRight size={20}/> : <ArrowDownRight size={20}/>}
                             </div>
                             <div>
                                <p className="font-black text-slate-800">{op.itemName}</p>
                                <div className="flex flex-col md:flex-row md:items-center text-[10px] text-slate-400 font-bold uppercase gap-2">
                                   <span className="flex items-center"><UserIcon size={10} className="mr-1"/> {op.user}</span>
                                   <span className="flex items-center"><Calendar size={10} className="mr-1"/> {new Date(op.timestamp).toLocaleString()}</span>
                                   {op.recipientName && (
                                       <span className="flex items-center text-blue-500"><Scan size={10} className="mr-1"/> Retirado por: {op.recipientName}</span>
                                   )}
                                </div>
                             </div>
                          </div>
                          <div className="text-right">
                             <p className={`text-lg font-black ${op.type === 'Entrada' ? 'text-emerald-500' : 'text-rose-500'}`}>
                                {op.type === 'Entrada' ? '+' : '-'}{op.quantity}
                             </p>
                             {op.reason && <p className="text-[9px] text-slate-400 font-medium">{op.reason}</p>}
                          </div>
                       </div>
                    ))
                 )}
              </div>
           </div>
        </div>
      )}

      {/* Modal FORNECEDOR */}
      {isAddingSupplier && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">Novo Fornecedor</h2>
                 <button onClick={() => setIsAddingSupplier(false)} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveSupplierSubmit} className="p-8 space-y-4">
                 <input type="text" value={supName} onChange={e => setSupName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Nome da Empresa" required />
                 <input type="text" value={supContact} onChange={e => setSupContact(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Contato (WhatsApp/Email)" />
                 <input type="text" value={supCategory} onChange={e => setSupCategory(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Categoria" />
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl" style={{ backgroundColor: theme.primary }}>Cadastrar Fornecedor</button>
              </form>
           </div>
        </div>
      )}


      {/* Modal NOVO ITEM */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">{editingItem ? 'Editar Insumo' : 'Novo Insumo'}</h2>
                 <p className="text-[10px] font-black text-slate-400 uppercase">{currentSector?.name}</p>
                 <button onClick={resetItemForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveItemSubmit} className="p-8 space-y-4">
                 <div className="grid grid-cols-1 gap-4">
                    <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none font-bold" placeholder="Nome do Insumo" required />
                    <div className="relative">
                       <Barcode size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" />
                       <input type="text" value={ean} onChange={e => setEan(e.target.value)} className="w-full pl-10 pr-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Código EAN (Obrigatório)" required />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                       <select value={category} onChange={e => setCategory(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold">
                          {categories.map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                       <select value={unit} onChange={e => setUnit(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold">
                          <option value="Unidade">Unidade</option>
                          <option value="Caixa">Caixa</option>
                          <option value="Litro">Litro</option>
                          <option value="Kg">Kg</option>
                       </select>
                    </div>
                    <select value={supplierId} onChange={e => setSupplierId(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold">
                       <option value="">Selecione o Fornecedor...</option>
                       {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                    <div className="grid grid-cols-2 gap-4">
                       <div className="p-4 bg-slate-50 rounded-2xl">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">Saldo Inicial</label>
                          <input type="number" value={initialQuantity} onChange={e => setInitialQuantity(parseInt(e.target.value) || 0)} className="w-full bg-transparent text-xl font-black outline-none" />
                       </div>
                       <div className="p-4 bg-slate-50 rounded-2xl">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">R$ Valor Unitário</label>
                          <input type="number" step="0.01" value={price} onChange={e => setPrice(parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-xl font-black outline-none" />
                       </div>
                    </div>
                 </div>
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl" style={{ backgroundColor: theme.primary }}>Salvar Cadastro</button>
              </form>
           </div>
        </div>
      )}

      {/* ... (MOVIMENTAÇÃO and FORNECEDOR modals remain the same) ... */}
      {isAddingOp && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           {/* ... Same Op Modal content as before ... */}
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">Lançar Movimentação</h2>
                 <button onClick={resetOpForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                const selectedItem = inventory.find(i => i.id === opItemId);
                if (!selectedItem || opQuantity <= 0) return;

                const finalRecipientName = opRecipientName || (opType === 'Saída' ? 'Não Identificado' : '');

                onOperation({ 
                    id: Date.now().toString(), 
                    itemId: opItemId, 
                    itemName: selectedItem.name, 
                    type: opType, 
                    quantity: opQuantity, 
                    timestamp: Date.now(), 
                    user: currentUser || 'Sistema', 
                    reason: opReason,
                    recipientId: opRecipientId,
                    recipientName: finalRecipientName
                });
                resetOpForm();
              }} className="p-8 space-y-6">
                 <div className="space-y-4">
                    <div className="relative" ref={searchContainerRef}>
                       <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1">Buscar Insumo (Nome ou EAN)</label>
                       <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                          <input 
                            type="text" 
                            value={opSearchQuery} 
                            onChange={e => { setOpSearchQuery(e.target.value); setIsSearchDropdownOpen(true); if(opItemId) setOpItemId(''); }} 
                            onFocus={() => setIsSearchDropdownOpen(true)}
                            className="w-full pl-9 pr-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none focus:border-blue-300 transition-all" 
                            placeholder="Digite o nome ou bipe o EAN..." 
                            autoComplete="off"
                          />
                       </div>

                       {isSearchDropdownOpen && predictiveResults.length > 0 && (
                         <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 z-[310] overflow-hidden animate-in fade-in slide-in-from-top-2">
                            {predictiveResults.map(i => (
                              <button key={i.id} type="button" onClick={() => handleSelectPredictiveItem(i)} className="w-full p-4 hover:bg-slate-50 text-left border-b border-slate-50 last:border-none flex items-center justify-between transition-colors">
                                 <div>
                                    <p className="font-black text-slate-800 text-sm">{i.name}</p>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase">{i.category} • EAN: {i.ean || 'N/A'}</p>
                                 </div>
                                 <div className="text-right">
                                    <p className="text-xs font-black text-slate-800">{i.quantity} {i.unit}</p>
                                    <p className="text-[8px] text-slate-400 uppercase">Saldo Atual</p>
                                 </div>
                              </button>
                            ))}
                         </div>
                       )}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                       <div className="flex bg-slate-50 p-1 rounded-xl border border-slate-100">
                          <button type="button" onClick={() => setOpType('Entrada')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${opType === 'Entrada' ? 'bg-white shadow-sm text-emerald-500' : 'text-slate-400'}`}>Entrada</button>
                          <button type="button" onClick={() => setOpType('Saída')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${opType === 'Saída' ? 'bg-white shadow-sm text-rose-500' : 'text-slate-400'}`}>Saída</button>
                       </div>
                       <input type="number" value={opQuantity || ''} onChange={e => setOpQuantity(parseInt(e.target.value) || 0)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none" placeholder="Quantidade" required />
                    </div>

                    {opType === 'Saída' && (
                        <div className="relative">
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1 flex items-center justify-between">
                                <span>Retirado por (Funcionário)</span>
                                <span className="flex items-center text-blue-500"><QrCode size={10} className="mr-1"/> Scan Ativo</span>
                            </label>
                            <div className="relative">
                                <Scan className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                                <input 
                                    ref={recipientInputRef}
                                    type="text" 
                                    value={opRecipientName} 
                                    onChange={handleScanRecipient}
                                    className="w-full pl-9 pr-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none focus:border-blue-300 transition-all bg-blue-50/50" 
                                    placeholder="Bipe o Crachá ou digite o nome..." 
                                    autoComplete="off"
                                />
                                {opRecipientName && (
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2">
                                        {opRecipientId ? (
                                            <CheckCircle2 size={18} className="text-emerald-500" />
                                        ) : (
                                            <span className="text-[9px] font-bold text-slate-400">Manual</span>
                                        )}
                                    </div>
                                )}
                            </div>
                            {/* Autocomplete for employees if typing manually */}
                            {opRecipientName && !opRecipientId && employeePredictive.length > 0 && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-lg border border-slate-100 z-[320] overflow-hidden">
                                    {employeePredictive.map(emp => (
                                        <button 
                                            key={emp.id} 
                                            type="button" 
                                            onClick={() => { setOpRecipientId(emp.id); setOpRecipientName(emp.name); }}
                                            className="w-full p-3 text-left hover:bg-slate-50 text-xs font-bold text-slate-700 border-b last:border-none"
                                        >
                                            {emp.name} <span className="text-slate-400">({emp.role})</span>
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    <input type="text" value={opReason} onChange={e => setOpReason(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none" placeholder="Motivo / Justificativa" />
                 </div>
                 <button type="submit" disabled={!opItemId} className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 disabled:opacity-50 disabled:grayscale" style={{ backgroundColor: theme.primary }}>Confirmar Movimentação</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default InventoryView;

import React, { useState, useMemo } from 'react';
import { Employee, HotelTheme, Sector, UniformItem, ExtraLabor, InventoryOperation } from '../types';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Building2,
  X,
  Plus,
  Clock,
  AlertTriangle,
  CheckCircle2,
  ChevronLeft,
  Edit2,
  Calendar as CalendarIcon,
  User as UserIcon,
  Printer,
  CalendarDays,
  Briefcase,
  Users,
  Star,
  MessageSquare,
  Phone,
  QrCode,
  Download,
  History,
  Package
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  extras: ExtraLabor[];
  sectors: Sector[];
  inventoryHistory?: InventoryOperation[];
  selectedSectorId: string | null;
  onSelectSector: (id: string | null) => void;
  theme: HotelTheme;
  onSave: (employee: Employee) => void;
  onDelete: (id: string) => void;
  onSaveExtra: (extra: ExtraLabor) => void;
  onDeleteExtra: (id: string) => void;
  onSaveSector: (sector: Sector) => void;
  onDeleteSector: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  extras,
  sectors, 
  inventoryHistory = [],
  selectedSectorId, 
  onSelectSector, 
  theme, 
  onSave, 
  onDelete, 
  onSaveExtra,
  onDeleteExtra,
  onSaveSector, 
  onDeleteSector 
}) => {
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingExtra, setIsAddingExtra] = useState(false);
  const [editingExtra, setEditingExtra] = useState<ExtraLabor | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'LIST' | 'SCALE' | 'TODAY' | 'EXTRAS'>('LIST');
  const [activeFormTab, setActiveFormTab] = useState<'DADOS' | 'ESCALA' | 'UNIFORMES'>('DADOS');
  const [selectedBadge, setSelectedBadge] = useState<Employee | null>(null);
  const [viewingHistoryEmployee, setViewingHistoryEmployee] = useState<Employee | null>(null);

  // Form State Employee
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [gender, setGender] = useState<'M' | 'F'>('M');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [salary, setSalary] = useState('');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('08:00 - 16:20');
  const [fixedDayOff, setFixedDayOff] = useState('Segunda-feira');
  const [sundayOffs, setSundayOffs] = useState<number[]>([]);
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');

  // Form State Extra
  const [extraName, setExtraName] = useState('');
  const [extraPhone, setExtraPhone] = useState('');
  const [extraAvailability, setExtraAvailability] = useState<string[]>([]);
  const [extraQuality, setExtraQuality] = useState(5);
  const [extraObservation, setExtraObservation] = useState('');

  // Form Sector
  const [sectorName, setSectorName] = useState('');

  const weekDays = ['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];

  const resetEmployeeForm = () => {
    setName(''); setRole(''); setGender('M'); setContact(''); setSalary('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setUniforms([]); setScheduleType('6x1'); setShiftType('Par');
    setWorkingHours('08:00 - 16:20'); setFixedDayOff('Segunda-feira');
    setSundayOffs([]); setVacationStatus('Pendente');
    setIsAddingEmployee(false); setEditingEmployee(null); setActiveFormTab('DADOS');
  };

  const resetExtraForm = () => {
    setExtraName(''); setExtraPhone(''); setExtraAvailability([]); setExtraQuality(5); setExtraObservation('');
    setIsAddingExtra(false); setEditingExtra(null);
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name || ''); setRole(emp.role || ''); setGender(emp.gender || 'M');
    setContact(emp.contact || ''); setStartDate(emp.startDate || ''); setSalary((emp.salary || 0).toString());
    setUniforms(emp.uniforms || []); setScheduleType(emp.scheduleType || '6x1');
    setShiftType(emp.shiftType || 'Par'); setWorkingHours(emp.workingHours || '08:00 - 16:20');
    setFixedDayOff(emp.fixedDayOff || 'Segunda-feira');
    setSundayOffs(emp.sundayOffs || []); setVacationStatus(emp.vacationStatus || 'Pendente');
    setIsAddingEmployee(true);
  };

  const handleEditExtra = (ext: ExtraLabor) => {
    setEditingExtra(ext);
    setExtraName(ext.name || ''); setExtraPhone(ext.phone || ''); 
    setExtraAvailability(ext.availability || []); setExtraQuality(ext.serviceQuality || 5);
    setExtraObservation(ext.observation || '');
    setIsAddingExtra(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId && !editingEmployee) return;

    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', 
      role: role || 'Cargo', 
      gender, 
      contact, 
      startDate,
      salary: parseFloat(salary) || 0, 
      department: sectors.find(s => s.id === (selectedSectorId || editingEmployee?.sectorId))?.name || '',
      sectorId: (selectedSectorId || editingEmployee?.sectorId)!, 
      status: 'Ativo', 
      scheduleType, 
      shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours: scheduleType === 'Intermitente' ? '' : workingHours, 
      fixedDayOff: scheduleType === '6x1' ? fixedDayOff : '', 
      sundayOffs: scheduleType === '6x1' ? sundayOffs : [], 
      weeklyDayOff: scheduleType === '6x1' ? fixedDayOff : '', 
      monthlySundayOff: '', 
      vacationStatus, 
      uniforms
    };
    onSave(newEmp);
    resetEmployeeForm();
  };

  const handleSaveExtraSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId && !editingExtra) return;

    const newExtra: ExtraLabor = {
      id: editingExtra?.id || Date.now().toString(),
      name: extraName,
      phone: extraPhone,
      availability: extraAvailability,
      serviceQuality: extraQuality,
      observation: extraObservation,
      sectorId: selectedSectorId || editingExtra?.sectorId || ''
    };
    onSaveExtra(newExtra);
    resetExtraForm();
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSaveSector({
      id: Date.now().toString(),
      name: sectorName,
      standardUniform: []
    });
    setSectorName('');
    setIsAddingSector(false);
  };

  const filteredEmployees = employees.filter(e => 
    e.sectorId === selectedSectorId && 
    (e.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredExtras = extras.filter(ext => 
    ext.sectorId === selectedSectorId &&
    (ext.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const currentSector = sectors.find(s => s.id === selectedSectorId);

  // Escala Logic
  const daysArray = useMemo(() => {
    const now = new Date();
    const days = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
    return Array.from({ length: days }, (_, i) => ({
      day: i + 1,
      name: new Date(now.getFullYear(), now.getMonth(), i + 1).toLocaleDateString('pt-BR', { weekday: 'long' }),
      isSunday: new Date(now.getFullYear(), now.getMonth(), i + 1).getDay() === 0
    }));
  }, []);

  const getSundayIndex = (day: number) => {
    const now = new Date();
    let count = 0;
    for(let i = 1; i <= day; i++) {
       if(new Date(now.getFullYear(), now.getMonth(), i).getDay() === 0) count++;
    }
    return count;
  };

  const todayInfo = useMemo(() => {
    const now = new Date();
    const weekday = now.toLocaleDateString('pt-BR', { weekday: 'long' });
    const day = now.getDate();
    let sundayIdx = 0;
    if (now.getDay() === 0) {
      let count = 0;
      for(let i = 1; i <= day; i++) {
        const d = new Date(now.getFullYear(), now.getMonth(), i);
        if(d.getDay() === 0) count++;
      }
      sundayIdx = count;
    }
    return { weekday, isSunday: now.getDay() === 0, sundayIdx, fullDate: now.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long' }) };
  }, []);

  const scheduledToday = useMemo(() => {
    return employees.filter(emp => {
      const isFixedOff = emp.fixedDayOff?.toLowerCase() === todayInfo.weekday.toLowerCase();
      const isSundayOff = todayInfo.isSunday && (emp.sundayOffs || []).includes(todayInfo.sundayIdx);
      return !isFixedOff && !isSundayOff && emp.status === 'Ativo';
    });
  }, [employees, todayInfo]);

  const groupedBySector = useMemo(() => {
    const groups: Record<string, Employee[]> = {};
    scheduledToday.forEach(emp => {
      const sector = sectors.find(s => s.id === emp.sectorId)?.name || 'Outros';
      if (!groups[sector]) groups[sector] = [];
      groups[sector].push(emp);
    });
    return groups;
  }, [scheduledToday, sectors]);

  // Lista de funcionários para a tabela de escala (exclui intermitentes)
  const scaleEmployees = useMemo(() => {
    return filteredEmployees.filter(e => e.scheduleType !== 'Intermitente');
  }, [filteredEmployees]);

  const employeeHistory = useMemo(() => {
    if(!viewingHistoryEmployee) return [];
    return inventoryHistory.filter(op => op.recipientId === viewingHistoryEmployee.id).sort((a,b) => b.timestamp - a.timestamp);
  }, [inventoryHistory, viewingHistoryEmployee]);

  // CALCULAR ITENS EMPRESTADOS (CAUTELA)
  const currentLoans = useMemo(() => {
    if(!selectedBadge) return [];

    const loans: Record<string, { name: string, qty: number }> = {};

    inventoryHistory.forEach(op => {
        if(op.recipientId === selectedBadge.id) {
            if(op.type === 'Saída') {
                // Se foi "Saída" do estoque com recipientId = funcionário, é uma ENTREGA para ele
                if(!loans[op.itemId]) loans[op.itemId] = { name: op.itemName, qty: 0 };
                loans[op.itemId].qty += op.quantity;
            } else if (op.type === 'Entrada') {
                // Se foi "Entrada" no estoque com recipientId = funcionário, é uma DEVOLUÇÃO dele
                if(loans[op.itemId]) {
                    loans[op.itemId].qty -= op.quantity;
                }
            }
        }
    });

    // Filtra apenas o que tem saldo positivo (ainda está com o funcionário)
    return Object.values(loans).filter(i => i.qty > 0);
  }, [selectedBadge, inventoryHistory]);


  if (!selectedSectorId && viewMode !== 'TODAY') {
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Painel de Equipe</p>
          <div className="flex gap-2">
            <button 
              onClick={() => setViewMode('TODAY')} 
              className="bg-white border-2 border-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-sm hover:border-blue-200 transition-all"
            >
              <CalendarDays size={18} /> <span>Escalados Hoje</span>
            </button>
            <button 
              onClick={() => setIsAddingSector(true)} 
              className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" 
              style={{ backgroundColor: theme.primary }}
            >
              <Plus size={18} /> <span>Novo Setor</span>
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {sectors.map((sec) => (
            <div key={sec.id} className="relative group">
               {/* Botão de Excluir Setor */}
              <button 
                onClick={(e) => { e.stopPropagation(); if(confirm('Tem certeza? Isso pode afetar dados vinculados.')) onDeleteSector(sec.id); }}
                className="absolute top-4 right-4 z-10 p-2 bg-white/80 rounded-full text-slate-300 hover:text-rose-500 hover:bg-white opacity-0 group-hover:opacity-100 transition-all"
              >
                <Trash2 size={16} />
              </button>

              <button onClick={() => onSelectSector(sec.id)} className="w-full bg-white h-48 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all border border-slate-50 flex flex-col items-center justify-center overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1.5" style={{ backgroundColor: theme.primary }}></div>
                <div className="p-5 rounded-2xl mb-3 bg-slate-50 text-slate-400 group-hover:scale-110 transition-transform">
                  <Building2 size={32} />
                </div>
                <h3 className="text-xl font-black text-slate-800">{sec.name}</h3>
                <p className="text-slate-400 text-[10px] font-black uppercase mt-1">
                  {employees.filter(e => e.sectorId === sec.id).length} Colaboradores
                </p>
              </button>
            </div>
          ))}
        </div>

        {isAddingSector && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
                <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
                   <h3 className="font-black text-slate-800">Novo Setor</h3>
                   <button onClick={() => setIsAddingSector(false)}><X size={24} className="text-slate-300"/></button>
                </div>
                <form onSubmit={handleSaveSectorSubmit} className="p-6 space-y-4">
                   <input 
                     type="text" 
                     value={sectorName} 
                     onChange={e => setSectorName(e.target.value)} 
                     placeholder="Nome do Setor (Ex: Recepção)" 
                     className="w-full px-4 py-3 rounded-xl border-2 font-bold text-slate-800 outline-none focus:border-blue-400" 
                     required 
                   />
                   <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black text-xs uppercase shadow-lg">Criar Setor</button>
                </form>
             </div>
          </div>
        )}
      </div>
    );
  }

  if (viewMode === 'TODAY') {
    return (
      <div className="space-y-6 animate-in fade-in duration-500 pb-20">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex justify-between items-center">
          <div className="flex items-center space-x-4">
            <button onClick={() => setViewMode('LIST')} className="p-2 bg-slate-50 rounded-xl text-slate-400"><ChevronLeft size={20} /></button>
            <div>
              <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Escalados Hoje</h2>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{todayInfo.weekday} • {todayInfo.fullDate}</p>
            </div>
          </div>
          <div className="bg-slate-50 px-4 py-2 rounded-xl border">
             <span className="text-lg font-black text-slate-800">{scheduledToday.length}</span>
             <span className="ml-2 text-[9px] font-black text-slate-400 uppercase">Presentes</span>
          </div>
        </div>

        <div className="space-y-8">
           {(Object.entries(groupedBySector) as [string, Employee[]][]).sort().map(([sectorName, list]) => (
             <div key={sectorName} className="space-y-4">
                <div className="flex items-center space-x-2 px-2">
                   <Briefcase size={16} className="text-slate-400" />
                   <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">{sectorName} ({list.length})</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                   {list.map(emp => (
                     <div key={emp.id} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between group">
                        <div className="flex items-center space-x-4">
                           <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg text-white shadow-md ${emp.gender === 'F' ? 'bg-rose-400' : 'bg-blue-400'}`}>
                              {(emp.name || 'S')[0]}
                           </div>
                           <div>
                              <p className="font-black text-slate-800 leading-none mb-1">{emp.name}</p>
                              <div className="flex items-center text-[9px] font-bold text-slate-400 uppercase tracking-tighter">
                                 <Clock size={10} className="mr-1" /> {emp.workingHours}
                              </div>
                           </div>
                        </div>
                     </div>
                   ))}
                </div>
             </div>
           ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="flex items-center space-x-3">
          <button onClick={() => onSelectSector(null)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-slate-600 transition-colors">
            <ChevronLeft size={20} />
          </button>
          <div>
            <h2 className="text-xl font-black text-slate-800 uppercase tracking-tighter">{currentSector?.name}</h2>
            <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">
                {viewMode === 'EXTRAS' ? `${filteredExtras.length} Profissionais` : `${filteredEmployees.length} Colaboradores`}
            </p>
          </div>
        </div>

        <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
          <button onClick={() => setViewMode('LIST')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'LIST' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Listagem</button>
          <button onClick={() => setViewMode('SCALE')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'SCALE' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Escala</button>
          <button onClick={() => setViewMode('EXTRAS')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'EXTRAS' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Extras</button>
        </div>

        {viewMode === 'EXTRAS' ? (
            <button onClick={() => setIsAddingExtra(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                <UserPlus size={18} /> <span className="hidden sm:inline">Cadastrar Extra</span>
            </button>
        ) : (
            <button onClick={() => setIsAddingEmployee(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                <UserPlus size={18} /> <span className="hidden sm:inline">Adicionar</span>
            </button>
        )}
      </div>

      {viewMode === 'LIST' && (
        <div className="space-y-4">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <input type="text" placeholder="Buscar colaborador..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 text-sm font-bold bg-white shadow-inner" />
          </div>

          <div className="grid grid-cols-1 gap-4">
            {filteredEmployees.map(emp => (
              <div key={emp.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row items-center gap-6 group hover:border-blue-200 transition-all">
                <div className="flex items-center space-x-4 flex-1">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-md ${emp.gender === 'F' ? 'bg-rose-400' : 'bg-blue-400'}`}>
                    {(emp.name || 'S')[0]}
                  </div>
                  <div>
                    <h4 className="font-black text-slate-800">{emp.name || 'Sem Nome'}</h4>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                       {emp.role} • {emp.scheduleType === 'Intermitente' ? 'Intermitente' : `Folga: ${emp.fixedDayOff || 'Rodízio'}`}
                    </p>
                  </div>
                </div>
                <div className="flex gap-4 items-center">
                  <div className="text-right hidden md:block">
                    <p className="text-[8px] font-black text-slate-300 uppercase">Status</p>
                    <span className="text-[9px] font-black text-emerald-500 uppercase flex items-center"><CheckCircle2 size={10} className="mr-1"/> Ativo</span>
                  </div>
                  <div className="flex space-x-2">
                    <button 
                       onClick={() => setSelectedBadge(emp)}
                       className="p-3 bg-slate-50 text-slate-400 hover:text-blue-500 rounded-xl transition-all border border-transparent hover:border-blue-200"
                       title="Crachá & Cautela"
                    >
                       <QrCode size={18}/>
                    </button>
                    <button 
                       onClick={() => setViewingHistoryEmployee(emp)}
                       className="p-3 bg-slate-50 text-slate-400 hover:text-amber-500 rounded-xl transition-all border border-transparent hover:border-amber-200"
                       title="Histórico Completo"
                    >
                       <History size={18}/>
                    </button>
                    <button onClick={() => handleEditEmployee(emp)} className="p-3 bg-slate-50 text-slate-400 hover:text-blue-500 rounded-xl transition-all border border-transparent hover:border-blue-200"><Edit2 size={18}/></button>
                    <button onClick={() => onDelete(emp.id)} className="p-3 bg-slate-50 text-slate-400 hover:text-rose-500 rounded-xl transition-all border border-transparent hover:border-rose-200"><Trash2 size={18}/></button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* MODAL DO CRACHÁ + CAUTELA (ITENS EMPRESTADOS) */}
      {selectedBadge && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[500] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-4xl rounded-[3rem] shadow-2xl flex flex-col max-h-[90vh] overflow-hidden animate-in zoom-in duration-300">
              <div className="p-6 border-b flex justify-between items-center bg-slate-50">
                 <h3 className="text-lg font-black text-slate-800 uppercase tracking-tighter flex items-center">
                    <QrCode size={20} className="mr-2"/> Identificação & Cautela
                 </h3>
                 <button onClick={() => setSelectedBadge(null)} className="p-2 text-slate-400 hover:text-slate-900 rounded-full"><X size={24}/></button>
              </div>

              <div className="flex-1 overflow-y-auto p-8" id="badge-print-area">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-10 print:block">

                     {/* LADO A: CRACHÁ VISUAL */}
                     <div className="flex flex-col items-center justify-center space-y-4 print:mb-8 print:break-inside-avoid">
                        <div className="w-[300px] h-[450px] bg-white rounded-[20px] shadow-xl border border-slate-200 relative overflow-hidden flex flex-col print:border-2 print:shadow-none">
                            <div className="h-32 w-full absolute top-0 left-0" style={{ backgroundColor: theme.primary }}></div>
                            <div className="relative z-10 flex flex-col items-center mt-12">
                                <div className="w-32 h-32 bg-white rounded-full p-1.5 shadow-lg mb-4">
                                   <div className={`w-full h-full rounded-full flex items-center justify-center text-4xl font-black text-white ${selectedBadge.gender === 'F' ? 'bg-rose-400' : 'bg-blue-400'}`}>
                                      {(selectedBadge.name || 'C')[0]}
                                   </div>
                                </div>
                                <h2 className="text-xl font-black text-slate-800 text-center px-4 leading-tight">{selectedBadge.name}</h2>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">{selectedBadge.role}</p>
                            </div>
                            <div className="mt-8 px-8 space-y-4">
                                <div className="flex justify-between border-b border-slate-100 pb-2">
                                    <span className="text-[10px] font-black text-slate-400 uppercase">Setor</span>
                                    <span className="text-[10px] font-bold text-slate-700">{selectedBadge.department}</span>
                                </div>
                                <div className="flex justify-between border-b border-slate-100 pb-2">
                                    <span className="text-[10px] font-black text-slate-400 uppercase">Admissão</span>
                                    <span className="text-[10px] font-bold text-slate-700">{new Date(selectedBadge.startDate).toLocaleDateString()}</span>
                                </div>
                                <div className="flex justify-center pt-4">
                                   <QrCode size={64} className="text-slate-800"/>
                                </div>
                            </div>
                            <div className="absolute bottom-4 w-full text-center">
                                <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.2em]">Nacional Inn</p>
                            </div>
                        </div>
                     </div>

                     {/* LADO B: LISTA DE ITENS EMPRESTADOS (CAUTELA) */}
                     <div className="print:break-inside-avoid">
                        <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 h-full print:bg-white print:border-0 print:p-0">
                           <div className="mb-6 border-b border-slate-200 pb-4">
                              <h4 className="font-black text-slate-800 text-lg uppercase tracking-tight">Termo de Responsabilidade</h4>
                              <p className="text-[10px] text-slate-500 font-medium mt-1 leading-relaxed text-justify">
                                Declaro ter recebido os itens abaixo relacionados, comprometendo-me a zelar pela sua guarda e conservação, assumindo a responsabilidade por qualquer dano ou extravio.
                              </p>
                           </div>

                           <div className="space-y-3 mb-8">
                              <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Itens em Posse (Cautela Ativa)</h5>
                              {currentLoans.length === 0 ? (
                                 <div className="p-4 bg-white rounded-xl border border-dashed border-slate-200 text-center">
                                    <Package size={24} className="mx-auto text-slate-300 mb-2"/>
                                    <p className="text-xs font-bold text-slate-400">Nenhum item emprestado no momento.</p>
                                 </div>
                              ) : (
                                 <table className="w-full text-left">
                                    <thead>
                                       <tr className="border-b border-slate-200">
                                          <th className="py-2 text-[10px] font-black text-slate-500 uppercase">Item</th>
                                          <th className="py-2 text-[10px] font-black text-slate-500 uppercase text-right">Qtd</th>
                                       </tr>
                                    </thead>
                                    <tbody>
                                       {currentLoans.map((item, idx) => (
                                          <tr key={idx} className="border-b border-slate-100">
                                             <td className="py-3 text-xs font-bold text-slate-700">{item.name}</td>
                                             <td className="py-3 text-xs font-black text-slate-900 text-right">{item.qty}</td>
                                          </tr>
                                       ))}
                                    </tbody>
                                 </table>
                              )}
                           </div>

                           <div className="mt-12 pt-8 border-t-2 border-slate-300">
                              <p className="text-center text-[10px] font-black uppercase text-slate-400 mb-8">Assinatura do Colaborador</p>
                              <div className="text-center text-xs font-bold text-slate-800">{selectedBadge.name}</div>
                              <div className="text-center text-[10px] text-slate-400">{new Date().toLocaleDateString()}</div>
                           </div>
                        </div>
                     </div>
                  </div>
              </div>

              <div className="p-6 border-t bg-slate-50 flex justify-end">
                 <button 
                   onClick={() => window.print()}
                   className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl flex items-center space-x-2 hover:bg-slate-800 transition-all active:scale-95"
                 >
                    <Printer size={16}/> <span>Imprimir Termo & Crachá</span>
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* Modal Histórico (Opções anteriores) */}
      {viewingHistoryEmployee && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[500] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl flex flex-col max-h-[80vh] overflow-hidden animate-in zoom-in duration-300">
              <div className="p-6 border-b flex justify-between items-center">
                 <h3 className="text-lg font-black text-slate-800">Histórico de Movimentações</h3>
                 <button onClick={() => setViewingHistoryEmployee(null)}><X size={24} className="text-slate-400"/></button>
              </div>
              <div className="flex-1 overflow-y-auto p-6 space-y-4">
                 {employeeHistory.length === 0 ? (
                    <p className="text-center text-slate-400 font-bold italic py-10">Nenhum registro encontrado.</p>
                 ) : (
                    employeeHistory.map(op => (
                       <div key={op.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center">
                          <div>
                             <p className="font-black text-slate-800 text-sm">{op.itemName}</p>
                             <p className="text-[10px] text-slate-400 uppercase font-bold">{new Date(op.timestamp).toLocaleString()}</p>
                          </div>
                          <div className={`px-3 py-1 rounded-lg text-xs font-black uppercase ${op.type === 'Saída' ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                             {op.type === 'Saída' ? 'Retirada' : 'Devolução'} ({op.quantity})
                          </div>
                       </div>
                    ))
                 )}
              </div>
           </div>
        </div>
      )}

      {/* Modal Cadastro/Edição de Funcionário CLT */}
      {isAddingEmployee && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-3xl rounded-[3rem] shadow-2xl max-h-[90vh] overflow-hidden flex flex-col animate-in zoom-in duration-300">
              <div className="p-8 border-b flex justify-between items-center bg-slate-50/50">
                 <div>
                    <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">{editingEmployee ? 'Editar' : 'Novo'} Colaborador</h2>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{currentSector?.name}</p>
                 </div>
                 <button onClick={resetEmployeeForm} className="p-2 text-slate-300 hover:text-slate-900 transition-all"><X size={32}/></button>
              </div>

              <div className="flex bg-slate-100 p-1.5 mx-8 mt-6 rounded-2xl border">
                 <button onClick={() => setActiveFormTab('DADOS')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'DADOS' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Dados Pessoais</button>
                 <button onClick={() => setActiveFormTab('ESCALA')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'ESCALA' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Escala & Folgas</button>
                 <button onClick={() => setActiveFormTab('UNIFORMES')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'UNIFORMES' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Uniformes</button>
              </div>

              <form onSubmit={handleSaveEmployeeSubmit} className="p-8 flex-1 overflow-y-auto space-y-8">
                 {activeFormTab === 'DADOS' && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-left-4">
                       <div className="col-span-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Nome Completo</label>
                          <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" required />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Gênero</label>
                          <div className="flex gap-2">
                             <button type="button" onClick={() => setGender('M')} className={`flex-1 py-3 rounded-xl border-2 font-black text-xs ${gender === 'M' ? 'bg-blue-500 border-blue-500 text-white shadow-md' : 'bg-white text-slate-400'}`}>MASCULINO</button>
                             <button type="button" onClick={() => setGender('F')} className={`flex-1 py-3 rounded-xl border-2 font-black text-xs ${gender === 'F' ? 'bg-rose-500 border-rose-500 text-white shadow-md' : 'bg-white text-slate-400'}`}>FEMININO</button>
                          </div>
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Cargo / Função</label>
                          <input type="text" value={role} onChange={e => setRole(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" required />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Telefone de Contato</label>
                          <input type="text" value={contact} onChange={e => setContact(e.target.value)} placeholder="(00) 00000-0000" className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Data de Admissão</label>
                          <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Salário Base (R$)</label>
                          <input type="number" value={salary} onChange={e => setSalary(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                       </div>
                    </div>
                 )}

                 {/* ... (ESCALA tab and UNIFORMES tab remain the same) ... */}
                 {activeFormTab === 'ESCALA' && (
                    <div className="space-y-8 animate-in slide-in-from-right-4">
                       <div className="col-span-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Tipo de Escala</label>
                          <div className="flex gap-2">
                             {(['6x1', '12x36', 'Intermitente'] as const).map(type => (
                               <button 
                                 key={type}
                                 type="button" 
                                 onClick={() => setScheduleType(type)}
                                 className={`flex-1 py-3 rounded-xl border-2 font-black text-[10px] uppercase transition-all ${scheduleType === type ? 'bg-slate-900 border-slate-900 text-white shadow-md' : 'bg-white text-slate-400 hover:border-slate-300'}`}
                               >
                                 {type}
                               </button>
                             ))}
                          </div>
                       </div>
                       {/* ... rest of the scale logic ... */}
                    </div>
                 )}
                 {/* ... */}

                 <div className="flex gap-4 pt-6 mt-6 border-t">
                    <button type="button" onClick={resetEmployeeForm} className="flex-1 py-4 font-black uppercase text-xs text-slate-400">Cancelar</button>
                    <button type="submit" className="flex-1 py-4 rounded-[1.5rem] font-black uppercase text-xs text-white shadow-xl active:scale-95 transition-all" style={{ backgroundColor: theme.primary }}>Salvar Colaborador</button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default EmployeesView;

export enum ViewType {
  DASHBOARD = 'DASHBOARD',
  APARTMENTS = 'APARTMENTS',
  BUDGETS = 'BUDGETS',
  SETTINGS = 'SETTINGS',
  EMPLOYEES = 'EMPLOYEES',
  INVENTORY = 'INVENTORY',
  REPORTS = 'REPORTS',
  TODAY_SCHEDULE = 'TODAY_SCHEDULE'
}

