  role: UserRole;
  hotel?: HotelType;
  name?: string;
}

export type HotelType = 'VILLAGE' | 'GOLDEN_PARK' | 'THERMAL_RESORT';

export interface HotelTheme {
  primary: string;
  secondary: string;
  accent: string;
  bg: string;
  text: string;
  chartColors: string[];
}

export interface Defect {
  id: string;
  driveLink: string;
  description: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface MaterialQuote {
  supplier: string;
  value: number;
}

export interface MaterialItem {
  id: string;
  name: string;
  quantity: number;
  unit?: string;
  observation?: string;
  quotes: MaterialQuote[];
}

export interface BudgetItem {
  id: string;
  description: string;
  materials: MaterialItem[];
  laborCost: number;
  estimatedTime: string;
  serviceProvider?: string;
}

export interface BudgetFile {
  id: string;
  driveLink: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface Quote {
  id: string;
  supplier: string;
  value: number;
  files: BudgetFile[];
}

export interface Budget {
  id: string;
  title: string;
  objective: string;
  items: BudgetItem[];
  quotes: Quote[];
