export interface UniformItem {
  name: string;
  quantity: number;
}

export interface Sector {
  id: string;
  name: string;
  standardUniform: UniformItem[];
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  gender: 'M' | 'F';
  contact: string;
  startDate: string;
  salary: number;
  department: string;
  sectorId: string;
  status: 'Ativo' | 'Inativo';
  scheduleType: '6x1' | '12x36' | 'Intermitente';
  shiftType?: 'Par' | 'Ímpar';
  workingHours: string;
  fixedDayOff: string;
  sundayOffs: number[];
  monthlySundayOff: string;
  weeklyDayOff: string;
  vacationStatus: 'Pendente' | 'Concedida';
  uniforms: UniformItem[];
  photo?: string; // Added photo support (Drive Link)
}

export interface ExtraLabor {
  id: string;
  name: string;
  phone: string;
  availability: string[]; // Dias da semana: ["Segunda", "Terça"...]
  serviceQuality: number; // 0 a 10
  observation: string;
  sectorId: string;
}

export interface Supplier {
  id: string;
  name: string;
  contact: string;
  category: string;
}

export interface InventoryItem {
  id: string;
  ean?: string;
  name: string;
  category: string;
  quantity: number;
  minQuantity: number;
  unit: string;
  price: number;
  supplierId?: string;
  sectorId?: string; // New field for sector organization
  lastUpdate: number;
}

export interface InventoryOperation {
  id: string;
  itemId: string;
  itemName: string;
  type: 'Entrada' | 'Saída';
  quantity: number;
  timestamp: number;
  user: string;
  reason?: string;
  recipientId?: string;
  recipientName?: string;
}

export interface Integration {
  id: string;
  name: string;
  type: 'Spreadsheet' | 'ExternalAPI';
  status: 'Connected' | 'Disconnected' | 'Pending';
