  url?: string;
}

export interface BedConfig {
  type: 'Casal' | 'Solteiro';
  baseStatus?: 'Nova' | 'Antiga';
  baseColor?: string;
  mattressStatus?: 'Novo' | 'Antigo';
  mattressColor?: string;
  hasSkirt?: boolean;
  skirtColor?: string;
}

export interface Apartment {
  id: string;
  floor: number;
  roomNumber: number;
  defects: Defect[];
  pisoType?: 'Granito' | 'Madeira' | 'Cerâmica';
  pisoStatus?: 'Bom estado' | 'Tolerável' | 'Reparo urgente';
  banheiroType?: 'Reformado' | 'Antigo';
  banheiroStatus?: 'Tolerável' | 'Reparo urgente';
  temCofre?: boolean;
  temCortina?: boolean;
  cortinaStatus?: 'Nova' | 'Antiga';
  cortinaSize?: string;
  cortinaCoverage?: 'Dois lados' | 'Um lado';
  temEspelhoCorpo?: boolean;
  espelhoCorpoStatus?: 'Bom estado' | 'Manchado' | 'Danificado';
  acBrand?: 'Midea' | 'LG' | 'Gree';
  moveisStatus?: 'Bom estado' | 'Danificado';
  moveisDetalhes?: string[];
  beds?: BedConfig[];
  temPortaControle?: boolean;
  temCabide?: boolean;
  cabideQuantity?: number;
  temSuportePapel?: boolean;
  temSuporteShampoo?: boolean;
  suporteShampooStatus?: 'Bom estado' | 'Enferrujado';
  luminariaType?: 'Arandela' | 'Vidro' | 'Quadrado';
  luminariaColor?: 'Branco' | 'Preto';
  tvBrand?: 'LG' | 'Samsung' | 'Philco' | 'Smart Roku' | 'Toshiba';
}

export interface HotelData {
  apartments: Record<string, Apartment>;
  budgets: Budget[];
  employees: Employee[];
  extras: ExtraLabor[];
  sectors: Sector[];
  inventory: InventoryItem[];
  inventoryHistory: InventoryOperation[];
  suppliers: Supplier[];
  config?: {
    showSuppliersTab: boolean;
  };
}

export interface AppState {
  currentView: ViewType;
  currentHotel: HotelType;
  hotels: Record<HotelType, HotelData>;
  selectedFloor: number | null;
  selectedApartmentId: string | null;
  selectedSectorId: string | null;
  integrations: Integration[];
  currentUser: User | null;
}

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector, InventoryItem, InventoryOperation, Supplier, ExtraLabor } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import InventoryView from './components/InventoryView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';

const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyHwnTqgnBMecAsscAIJgpfe7gHPwjWbZ42qbm3EvXvX_oq9WzbrrT99knh7L4wdvDe4g/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  extras: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const initialSyncRef = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    // Incrementado para V43 para garantir limpeza de cache com novos campos
    const saved = localStorage.getItem('hotel_village_state_v43');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return { ...parsed, currentUser: null };
      } catch (e) {
        console.error("Erro ao carregar estado salvo:", e);
      }
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    const targetHotel = hotelOverride || state.currentHotel;
    setIsRefreshing(true);
    try {
      // Usa URL do estado se disponível, senão usa a constante
      const scriptUrl = state.integrations[0]?.url || GLOBAL_SCRIPT_URL;
      const fetchUrl = `${scriptUrl}?hotel=${targetHotel}&nocache=${Date.now()}`;

      const response = await fetch(fetchUrl, {
        method: 'GET',
        mode: 'cors',
        redirect: 'follow'
      });

      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const result = await response.json();

      if (result && result.status === 'success') {
        const incomingData = result.data;

        // NORMALIZAÇÃO RIGOROSA DE FUNCIONÁRIOS
        const normalizedEmployees = (incomingData.employees || []).map((emp: any) => {
          let sOffs: number[] = [];
          if (typeof emp.sundayOffs === 'string' && emp.sundayOffs !== '') {
            try {
              const p = JSON.parse(emp.sundayOffs);
              sOffs = Array.isArray(p) ? p.map(Number) : [Number(p)];
            } catch {
              sOffs = emp.sundayOffs.split(',').map(Number).filter(n => !isNaN(n));
            }
          } else if (Array.isArray(emp.sundayOffs)) {
            sOffs = emp.sundayOffs.map(Number);
          }

          return {
            ...emp,
            id: emp.id?.toString() || '',
            name: emp.name || 'Sem Nome',
            gender: (emp.gender?.toUpperCase() === 'F' || emp.gender?.toUpperCase() === 'FEMININO') ? 'F' : 'M',
            role: emp.role || '',
            fixedDayOff: emp.fixedDayOff || 'Segunda-feira',
            sundayOffs: sOffs,
            sectorId: emp.sectorId?.toString() || '',
            salary: parseFloat(emp.salary) || 0,
            uniforms: typeof emp.uniforms === 'string' ? JSON.parse(emp.uniforms) : (emp.uniforms || []),
            photo: emp.photo || '' // Normalized photo field
          };
        });

        // NORMALIZAÇÃO DE EXTRAS
        const normalizedExtras = (incomingData.extras || []).map((ext: any) => ({
          ...ext,
          id: ext.id?.toString() || '',
          name: ext.name || '',
          phone: ext.phone || '',
          availability: typeof ext.availability === 'string' ? JSON.parse(ext.availability) : (ext.availability || []),
          serviceQuality: parseFloat(ext.serviceQuality) || 0,
          sectorId: ext.sectorId?.toString() || '',
          observation: ext.observation || ''
        }));

        const normalizedSectors = (incomingData.sectors || []).map((sec: any) => ({
          ...sec,
          id: sec.id?.toString() || '',
          name: sec.name || 'Setor Sem Nome',
          standardUniform: typeof sec.standardUniform === 'string' ? JSON.parse(sec.standardUniform) : (sec.standardUniform || [])
        }));

        // NORMALIZAÇÃO DE ORÇAMENTOS
        const normalizedBudgets = (incomingData.budgets || []).map((b: any) => ({
          ...b,
          id: b.id?.toString() || '',
          title: b.title || 'Sem Título',
          objective: b.objective || '',
          items: (typeof b.items === 'string' ? JSON.parse(b.items) : (b.items || [])).map((it: any) => ({
            ...it,
            description: it.description || 'Serviço',
            materials: (it.materials || []).map((m: any) => ({
              ...m,
              quotes: m.quotes || [{ supplier: '', value: 0 }, { supplier: '', value: 0 }, { supplier: '', value: 0 }]
            }))
          })),
          quotes: typeof b.quotes === 'string' ? JSON.parse(b.quotes) : (b.quotes || []),
          files: typeof b.files === 'string' ? JSON.parse(b.files) : (b.files || []), // Normalized files
          createdAt: typeof b.createdAt === 'string' ? new Date(b.createdAt).getTime() : (b.createdAt || Date.now())
        }));

        // NORMALIZAÇÃO DE ESTOQUE
        const normalizedInventory = (incomingData.inventory || []).map((inv: any) => ({
            ...inv,
            id: inv.id?.toString(),
            quantity: parseFloat(inv.quantity) || 0,
            price: parseFloat(inv.price) || 0,
            lastUpdate: inv.lastUpdate ? new Date(inv.lastUpdate).getTime() : Date.now(),
            sectorId: inv.sectorId?.toString() || '' // Parse sectorId
        }));

        const normalizedInventoryHistory = (incomingData.inventoryHistory || []).map((op: any) => ({
            ...op,
            id: op.id?.toString(),
            quantity: parseFloat(op.quantity) || 0,
            timestamp: op.timestamp ? new Date(op.timestamp).getTime() : Date.now(),
            recipientName: op.recipientName || ''
        }));

        const normalizedSuppliers = (incomingData.suppliers || []).map((s: any) => ({
            ...s,
            id: s.id?.toString()
        }));

        const normalizedApartments: Record<string, Apartment> = {};
        Object.entries(incomingData.apartments || {}).forEach(([id, apt]: [string, any]) => {
          normalizedApartments[id] = {
            ...apt,
            defects: Array.isArray(apt.defects) ? apt.defects : [],
            beds: Array.isArray(apt.beds) ? apt.beds : [],
            moveisDetalhes: Array.isArray(apt.moveisDetalhes) ? apt.moveisDetalhes : []
          };
        });

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...incomingData,
              apartments: normalizedApartments,
              employees: normalizedEmployees,
              extras: normalizedExtras,
              sectors: normalizedSectors,
              budgets: normalizedBudgets,
              inventory: normalizedInventory,
              inventoryHistory: normalizedInventoryHistory,
              suppliers: normalizedSuppliers
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return incomingData;
      }
    } catch (error) { 
      console.warn(`Erro ao carregar ${targetHotel}:`, error);
    } finally { 
      setIsRefreshing(false); 
    }
    return null;
  }, [state.currentHotel, state.integrations]);

  useEffect(() => {
    if (initialSyncRef.current) return;
    initialSyncRef.current = true;
    const runSync = async () => {
      await loadDataFromSheet(state.currentHotel);
      const others = (['VILLAGE', 'GOLDEN_PARK', 'THERMAL_RESORT'] as HotelType[]).filter(h => h !== state.currentHotel);
      for (const h of others) {
        await delay(4500);
        await loadDataFromSheet(h);
      }
    };
    runSync();
  }, [loadDataFromSheet, state.currentHotel]);

  useEffect(() => { 
    localStorage.setItem('hotel_village_state_v43', JSON.stringify(state)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'EXTRA' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, newFiles?: any[]) => {
    try {
      const scriptUrl = state.integrations[0]?.url || GLOBAL_SCRIPT_URL;
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        body: JSON.stringify({
          hotel: state.currentHotel,
          dataType,
          ...data,
          newFiles
        })
      });
    } catch (e) {
      console.error("Erro na sincronização:", e);
    }
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const handleLogin = (user: User) => setState(prev => ({ ...prev, currentUser: user }));
  const handleLogout = () => setState(prev => ({ ...prev, currentUser: null, currentView: ViewType.DASHBOARD }));

  const handleViewChange = (view: ViewType) => setState(prev => ({ 
    ...prev, 
    currentView: view,
    selectedFloor: null,
    selectedApartmentId: null,
    selectedSectorId: null
  }));

  const handleHotelChange = (hotel: HotelType) => {
    setState(prev => ({ ...prev, currentHotel: hotel }));
    loadDataFromSheet(hotel);
  };

  const handleSaveApartment = (apt: Apartment, newFiles?: any[]) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          apartments: { ...prev.hotels[prev.currentHotel].apartments, [apt.id]: apt }
        }
      }
    }));
    syncToSheet('APARTMENT', apt, newFiles);
  };

  const handleSaveBudget = (budget: Budget, newFiles?: any[]) => {
    const existing = currentHotelData.budgets.find(b => b.id === budget.id);
    const newBudgets = existing 
      ? currentHotelData.budgets.map(b => b.id === budget.id ? budget : b)
      : [...currentHotelData.budgets, budget];

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], budgets: newBudgets }
      }
    }));
    // Pass newFiles to syncToSheet so they can be uploaded to Drive
    syncToSheet('BUDGET', budget, newFiles);
  };

  const handleDeleteBudget = (id: string) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          budgets: prev.hotels[prev.currentHotel].budgets.filter(b => b.id !== id)
        }
      }
    }));
    syncToSheet('DELETE', { id, targetType: 'BUDGET' });
  };

  const handleSaveEmployee = (emp: Employee, newFiles?: any[]) => {
    const existing = currentHotelData.employees.find(e => e.id === emp.id);
    const newEmps = existing 
      ? currentHotelData.employees.map(e => e.id === emp.id ? emp : e)
      : [...currentHotelData.employees, emp];

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], employees: newEmps }
      }
    }));
    // Pass newFiles (photo) to syncToSheet
    syncToSheet('EMPLOYEE', emp, newFiles);
  };

  const handleDeleteEmployee = (id: string) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)
        }
      }
    }));
    syncToSheet('DELETE', { id, targetType: 'EMPLOYEE' });
  };

  const handleSaveExtra = (extra: ExtraLabor) => {
    const existing = currentHotelData.extras.find(e => e.id === extra.id);
    const newExtras = existing 
      ? currentHotelData.extras.map(e => e.id === extra.id ? extra : e)
      : [...currentHotelData.extras, extra];

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], extras: newExtras }
      }
    }));
    syncToSheet('EXTRA', extra);
  };

  const handleDeleteExtra = (id: string) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          extras: prev.hotels[prev.currentHotel].extras.filter(e => e.id !== id)
        }
      }
    }));
    syncToSheet('DELETE', { id, targetType: 'EXTRA' });
  };

  const handleSaveSector = (sec: Sector) => {
    const existing = currentHotelData.sectors.find(s => s.id === sec.id);
    const newSectors = existing 
      ? currentHotelData.sectors.map(s => s.id === sec.id ? sec : s)
      : [...currentHotelData.sectors, sec];

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], sectors: newSectors }
      }
    }));
    syncToSheet('SECTOR', sec);
  };

  const handleDeleteSector = (id: string) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)
        }
      }
    }));
    syncToSheet('DELETE', { id, targetType: 'SECTOR' });
  };

  const handleSaveInventoryItem = (item: InventoryItem) => {
    const existing = currentHotelData.inventory.find(i => i.id === item.id);
    const newInv = existing 
      ? currentHotelData.inventory.map(i => i.id === item.id ? item : i)
      : [...currentHotelData.inventory, item];

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], inventory: newInv }
      }
    }));
    syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventoryItem = (id: string) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          inventory: prev.hotels[prev.currentHotel].inventory.filter(i => i.id !== id)
        }
      }
    }));
    syncToSheet('DELETE', { id, targetType: 'INVENTORY' });
  };

  const handleInventoryOperation = (op: InventoryOperation) => {
    const item = currentHotelData.inventory.find(i => i.id === op.itemId);
    if (!item) return;

    const newQty = op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity;
    const newItem = { ...item, quantity: newQty, lastUpdate: Date.now() };

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          inventory: prev.hotels[prev.currentHotel].inventory.map(i => i.id === op.itemId ? newItem : i),
          inventoryHistory: [op, ...prev.hotels[prev.currentHotel].inventoryHistory].slice(0, 100)
        }
      }
    }));
    syncToSheet('INVENTORY_OP', op);
  };

  const handleSaveSupplier = (sup: Supplier) => {
    const existing = currentHotelData.suppliers.find(s => s.id === sup.id);
    const newSups = existing 
      ? currentHotelData.suppliers.map(s => s.id === sup.id ? sup : s)
      : [...currentHotelData.suppliers, sup];

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], suppliers: newSups }
      }
    }));
    syncToSheet('SUPPLIER', sup);
  };

  const handleDeleteSupplier = (id: string) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          suppliers: prev.hotels[prev.currentHotel].suppliers.filter(s => s.id !== id)
        }
      }
    }));
    syncToSheet('DELETE', { id, targetType: 'SUPPLIER' });
  };

  const handleUpdateConfig = (config: any) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          config: { ...prev.hotels[prev.currentHotel].config, ...config }
        }
      }
    }));
    syncToSheet('CONFIG', config);
  };

  const handleUpdateIntegration = (integration: Integration) => {
    setState(prev => ({
      ...prev,
      integrations: prev.integrations.map(i => i.id === integration.id ? integration : i)
    }));
  };

  const renderContent = () => {
    if (state.selectedApartmentId) {
      let apt = currentHotelData.apartments[state.selectedApartmentId];
      if (!apt) {
        const parts = state.selectedApartmentId.split('-');
        const floor = parseInt(parts[0]);
        const roomNumber = parseInt(parts[1]);
        apt = {
          id: state.selectedApartmentId,
          floor,
          roomNumber,
          defects: [],
          beds: [],
          moveisDetalhes: []
        };
      }
      return (
        <ApartmentDetailView 
          apartment={apt} 
          theme={theme} 
          onBack={() => setState(prev => ({ ...prev, selectedApartmentId: null }))} 
          onSave={handleSaveApartment}
        />
      );
    }

    if (state.selectedFloor) {
      return (
        <FloorDetailView 
          floor={state.selectedFloor} 
          theme={theme} 
          apartments={currentHotelData.apartments} 
          onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))}
          onSelectApartment={(id) => setState(prev => ({ ...prev, selectedApartmentId: id }))}
        />
      );
    }

    switch (state.currentView) {
      case ViewType.DASHBOARD:
        return (
          <Dashboard 
            apartments={currentHotelData.apartments} 
            employees={currentHotelData.employees} 
            inventory={currentHotelData.inventory}
            sectors={currentHotelData.sectors}
            theme={theme} 
            lastSync={state.integrations[0].lastSync} 
            onRefresh={() => loadDataFromSheet()} 
            isRefreshing={isRefreshing} 
          />
        );
      case ViewType.APARTMENTS:
        return <ApartmentsView onSelectFloor={(floor) => setState(prev => ({ ...prev, selectedFloor: floor }))} theme={theme} hotelName={state.currentHotel} />;
      case ViewType.BUDGETS:
        return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={handleSaveBudget} onDelete={handleDeleteBudget} />;
      case ViewType.EMPLOYEES:
        return (
          <EmployeesView 
            employees={currentHotelData.employees} 
            extras={currentHotelData.extras}
            sectors={currentHotelData.sectors} 
            inventoryHistory={currentHotelData.inventoryHistory}
            selectedSectorId={state.selectedSectorId} 
            onSelectSector={(id) => setState(prev => ({ ...prev, selectedSectorId: id }))} 
            theme={theme} 
            onSave={handleSaveEmployee} 
            onDelete={handleDeleteEmployee} 
            onSaveExtra={handleSaveExtra}
            onDeleteExtra={handleDeleteExtra}
            onSaveSector={handleSaveSector} 
            onDeleteSector={handleDeleteSector} 
          />
        );
      case ViewType.INVENTORY:
        return (
          <InventoryView 
            inventory={currentHotelData.inventory} 
            history={currentHotelData.inventoryHistory} 
            suppliers={currentHotelData.suppliers}
            employees={currentHotelData.employees} 
            sectors={currentHotelData.sectors}
            showSuppliersTab={currentHotelData.config?.showSuppliersTab} 
            theme={theme} 
            onSave={handleSaveInventoryItem} 
            onDelete={handleDeleteInventoryItem} 
            onOperation={handleInventoryOperation} 
            onSaveSupplier={handleSaveSupplier} 
            onDeleteSupplier={handleDeleteSupplier}
            onSaveSector={handleSaveSector}
            onDeleteSector={handleDeleteSector}
            role={state.currentUser?.role} 
            currentUser={state.currentUser?.name} 
          />
        );
      case ViewType.REPORTS:
        return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={(id) => setState(prev => ({ ...prev, selectedApartmentId: id }))} />;
      case ViewType.SETTINGS:
        return (
          <SettingsView 
            integrations={state.integrations} 
            hotelConfig={currentHotelData.config} 
            onUpdateConfig={handleUpdateConfig} 
            theme={theme} 
            suppliers={currentHotelData.suppliers} 
            onSaveSupplier={handleSaveSupplier} 
            onDeleteSupplier={handleDeleteSupplier} 
            onUpdate={handleUpdateIntegration} 
          />
        );
      default:
        return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} />;
    }
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      <Sidebar 
        currentView={state.currentView} 
        onViewChange={handleViewChange} 
        currentHotel={state.currentHotel} 
        onHotelChange={handleHotelChange} 
        onLogout={handleLogout} 
        theme={theme} 
        role={state.currentUser.role} 
      />

      <main className="flex-1 p-4 md:p-8 md:ml-64 mb-20 md:mb-0 transition-all duration-300">
        <header className="flex justify-between items-center mb-8 md:hidden">
          <h1 className="text-2xl font-black text-slate-800 tracking-tighter">Nacional Inn</h1>
          <div className="px-3 py-1 bg-white rounded-full border text-[10px] font-bold text-slate-400 uppercase tracking-widest">{state.currentHotel}</div>
        </header>
        {renderContent()}
      </main>

      <BottomNav 
        currentView={state.currentView} 
        onViewChange={handleViewChange} 
        theme={theme} 
        role={state.currentUser.role} 
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { Employee, HotelTheme, Sector, UniformItem, ExtraLabor, InventoryOperation } from '../types';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Building2,
  X,
  Plus,
  Clock,
  AlertTriangle,
  CheckCircle2,
  ChevronLeft,
  Edit2,
  Calendar as CalendarIcon,
  User as UserIcon,
  Printer,
  CalendarDays,
  Briefcase,
  Users,
  Star,
  MessageSquare,
  Phone,
  QrCode,
  Download,
  History,
  Package,
  Camera
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  extras: ExtraLabor[];
  sectors: Sector[];
  inventoryHistory?: InventoryOperation[];
  selectedSectorId: string | null;
  onSelectSector: (id: string | null) => void;
  theme: HotelTheme;
  onSave: (employee: Employee, newFiles?: any[]) => void;
  onDelete: (id: string) => void;
  onSaveExtra: (extra: ExtraLabor) => void;
  onDeleteExtra: (id: string) => void;
  onSaveSector: (sector: Sector) => void;
  onDeleteSector: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  extras,
  sectors, 
  inventoryHistory = [],
  selectedSectorId, 
  onSelectSector, 
  theme, 
  onSave, 
  onDelete, 
  onSaveExtra,
  onDeleteExtra,
  onSaveSector, 
  onDeleteSector 
}) => {
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingExtra, setIsAddingExtra] = useState(false);
  const [editingExtra, setEditingExtra] = useState<ExtraLabor | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'LIST' | 'SCALE' | 'TODAY' | 'EXTRAS'>('LIST');
  const [activeFormTab, setActiveFormTab] = useState<'DADOS' | 'ESCALA' | 'UNIFORMES'>('DADOS');
  const [selectedBadge, setSelectedBadge] = useState<Employee | null>(null);
  const [viewingHistoryEmployee, setViewingHistoryEmployee] = useState<Employee | null>(null);

  // Form State Employee
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [gender, setGender] = useState<'M' | 'F'>('M');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [salary, setSalary] = useState('');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('08:00 - 16:20');
  const [fixedDayOff, setFixedDayOff] = useState('Segunda-feira');
  const [sundayOffs, setSundayOffs] = useState<number[]>([]);
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');

  // Photo State
  const [photoPreview, setPhotoPreview] = useState<string | null>(null);
  const [newPhotoFile, setNewPhotoFile] = useState<{data: string, mimeType: string, fileName: string} | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Form State Extra
  const [extraName, setExtraName] = useState('');
  const [extraPhone, setExtraPhone] = useState('');
  const [extraAvailability, setExtraAvailability] = useState<string[]>([]);
  const [extraQuality, setExtraQuality] = useState(5);
  const [extraObservation, setExtraObservation] = useState('');

  // Form Sector
  const [sectorName, setSectorName] = useState('');

  const weekDays = ['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];

  const resetEmployeeForm = () => {
    setName(''); setRole(''); setGender('M'); setContact(''); setSalary('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setUniforms([]); setScheduleType('6x1'); setShiftType('Par');
    setWorkingHours('08:00 - 16:20'); setFixedDayOff('Segunda-feira');
    setSundayOffs([]); setVacationStatus('Pendente');
    setPhotoPreview(null); setNewPhotoFile(null);
    setIsAddingEmployee(false); setEditingEmployee(null); setActiveFormTab('DADOS');
  };

  const resetExtraForm = () => {
    setExtraName(''); setExtraPhone(''); setExtraAvailability([]); setExtraQuality(5); setExtraObservation('');
    setIsAddingExtra(false); setEditingExtra(null);
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name || ''); setRole(emp.role || ''); setGender(emp.gender || 'M');
    setContact(emp.contact || ''); setStartDate(emp.startDate || ''); setSalary((emp.salary || 0).toString());
    setUniforms(emp.uniforms || []); setScheduleType(emp.scheduleType || '6x1');
    setShiftType(emp.shiftType || 'Par'); setWorkingHours(emp.workingHours || '08:00 - 16:20');
    setFixedDayOff(emp.fixedDayOff || 'Segunda-feira');
    setSundayOffs(emp.sundayOffs || []); setVacationStatus(emp.vacationStatus || 'Pendente');
    setPhotoPreview(emp.photo || null);
    setNewPhotoFile(null);
    setIsAddingEmployee(true);
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const fullBase64 = reader.result?.toString() || '';
        const base64Data = fullBase64.split(',')[1] || '';
        setPhotoPreview(fullBase64);
        setNewPhotoFile({ data: base64Data, mimeType: file.type, fileName: file.name });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleEditExtra = (ext: ExtraLabor) => {
    setEditingExtra(ext);
    setExtraName(ext.name || ''); setExtraPhone(ext.phone || ''); 
    setExtraAvailability(ext.availability || []); setExtraQuality(ext.serviceQuality || 5);
    setExtraObservation(ext.observation || '');
    setIsAddingExtra(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId && !editingEmployee) return;

    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', 
      role: role || 'Cargo', 
      gender, 
      contact, 
      startDate,
      salary: parseFloat(salary) || 0, 
      department: sectors.find(s => s.id === (selectedSectorId || editingEmployee?.sectorId))?.name || '',
      sectorId: (selectedSectorId || editingEmployee?.sectorId)!, 
      status: 'Ativo', 
      scheduleType, 
      shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours: scheduleType === 'Intermitente' ? '' : workingHours, 
      fixedDayOff: scheduleType === '6x1' ? fixedDayOff : '', 
      sundayOffs: scheduleType === '6x1' ? sundayOffs : [], 
      weeklyDayOff: scheduleType === '6x1' ? fixedDayOff : '', 
      monthlySundayOff: '', 
      vacationStatus, 
      uniforms,
      photo: editingEmployee?.photo || '' // Preserve old photo link if no new file
    };

    // Pass newPhotoFile as an array to syncToSheet via onSave
    onSave(newEmp, newPhotoFile ? [newPhotoFile] : undefined);
    resetEmployeeForm();
  };

  const handleSaveExtraSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId && !editingExtra) return;

    const newExtra: ExtraLabor = {
      id: editingExtra?.id || Date.now().toString(),
      name: extraName,
      phone: extraPhone,
      availability: extraAvailability,
      serviceQuality: extraQuality,
      observation: extraObservation,
      sectorId: selectedSectorId || editingExtra?.sectorId || ''
    };
    onSaveExtra(newExtra);
    resetExtraForm();
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSaveSector({
      id: Date.now().toString(),
      name: sectorName,
      standardUniform: []
    });
    setSectorName('');
    setIsAddingSector(false);
  };

  const filteredEmployees = employees.filter(e => 
    e.sectorId === selectedSectorId && 
    (e.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredExtras = extras.filter(ext => 
    ext.sectorId === selectedSectorId &&
    (ext.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const currentSector = sectors.find(s => s.id === selectedSectorId);

  // Escala Logic
  const daysArray = useMemo(() => {
    const now = new Date();
    const days = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
    return Array.from({ length: days }, (_, i) => ({
      day: i + 1,
      name: new Date(now.getFullYear(), now.getMonth(), i + 1).toLocaleDateString('pt-BR', { weekday: 'long' }),
      isSunday: new Date(now.getFullYear(), now.getMonth(), i + 1).getDay() === 0
    }));
  }, []);

  const getSundayIndex = (day: number) => {
    const now = new Date();
    let count = 0;
    for(let i = 1; i <= day; i++) {
       if(new Date(now.getFullYear(), now.getMonth(), i).getDay() === 0) count++;
    }
    return count;
  };

  const todayInfo = useMemo(() => {
    const now = new Date();
    const weekday = now.toLocaleDateString('pt-BR', { weekday: 'long' });
    const day = now.getDate();
    let sundayIdx = 0;
    if (now.getDay() === 0) {
      let count = 0;
      for(let i = 1; i <= day; i++) {
        const d = new Date(now.getFullYear(), now.getMonth(), i);
        if(d.getDay() === 0) count++;
      }
      sundayIdx = count;
    }
    return { weekday, isSunday: now.getDay() === 0, sundayIdx, fullDate: now.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long' }) };
  }, []);

  const scheduledToday = useMemo(() => {
    return employees.filter(emp => {
      const isFixedOff = emp.fixedDayOff?.toLowerCase() === todayInfo.weekday.toLowerCase();
      const isSundayOff = todayInfo.isSunday && (emp.sundayOffs || []).includes(todayInfo.sundayIdx);
      return !isFixedOff && !isSundayOff && emp.status === 'Ativo';
    });
  }, [employees, todayInfo]);

  const groupedBySector = useMemo(() => {
    const groups: Record<string, Employee[]> = {};
    scheduledToday.forEach(emp => {
      const sector = sectors.find(s => s.id === emp.sectorId)?.name || 'Outros';
      if (!groups[sector]) groups[sector] = [];
      groups[sector].push(emp);
    });
    return groups;
  }, [scheduledToday, sectors]);

  // Lista de funcionários para a tabela de escala (exclui intermitentes)
  const scaleEmployees = useMemo(() => {
    return filteredEmployees.filter(e => e.scheduleType !== 'Intermitente');
  }, [filteredEmployees]);

  const employeeHistory = useMemo(() => {
    if(!viewingHistoryEmployee) return [];
    return inventoryHistory.filter(op => op.recipientId === viewingHistoryEmployee.id).sort((a,b) => b.timestamp - a.timestamp);
  }, [inventoryHistory, viewingHistoryEmployee]);

  // CALCULAR ITENS EMPRESTADOS (CAUTELA)
  const currentLoans = useMemo(() => {
    if(!selectedBadge) return [];

    const loans: Record<string, { name: string, qty: number }> = {};

    inventoryHistory.forEach(op => {
        if(op.recipientId === selectedBadge.id) {
            if(op.type === 'Saída') {
                // Se foi "Saída" do estoque com recipientId = funcionário, é uma ENTREGA para ele
                if(!loans[op.itemId]) loans[op.itemId] = { name: op.itemName, qty: 0 };
                loans[op.itemId].qty += op.quantity;
            } else if (op.type === 'Entrada') {
                // Se foi "Entrada" no estoque com recipientId = funcionário, é uma DEVOLUÇÃO dele
                if(loans[op.itemId]) {
                    loans[op.itemId].qty -= op.quantity;
                }
            }
        }
    });

    // Filtra apenas o que tem saldo positivo (ainda está com o funcionário)
    return Object.values(loans).filter(i => i.qty > 0);
  }, [selectedBadge, inventoryHistory]);


  if (!selectedSectorId && viewMode !== 'TODAY') {
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Painel de Equipe</p>
          <div className="flex gap-2">
            <button 
              onClick={() => setViewMode('TODAY')} 
              className="bg-white border-2 border-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-sm hover:border-blue-200 transition-all"
            >
              <CalendarDays size={18} /> <span>Escalados Hoje</span>
            </button>
            <button 
              onClick={() => setIsAddingSector(true)} 
              className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" 
              style={{ backgroundColor: theme.primary }}
            >
              <Plus size={18} /> <span>Novo Setor</span>
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {sectors.map((sec) => (
            <div key={sec.id} className="relative group">
               {/* Botão de Excluir Setor */}
              <button 
                onClick={(e) => { e.stopPropagation(); if(confirm('Tem certeza? Isso pode afetar dados vinculados.')) onDeleteSector(sec.id); }}
                className="absolute top-4 right-4 z-10 p-2 bg-white/80 rounded-full text-slate-300 hover:text-rose-500 hover:bg-white opacity-0 group-hover:opacity-100 transition-all"
              >
                <Trash2 size={16} />
              </button>

              <button onClick={() => onSelectSector(sec.id)} className="w-full bg-white h-48 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all border border-slate-50 flex flex-col items-center justify-center overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1.5" style={{ backgroundColor: theme.primary }}></div>
                <div className="p-5 rounded-2xl mb-3 bg-slate-50 text-slate-400 group-hover:scale-110 transition-transform">
                  <Building2 size={32} />
                </div>
                <h3 className="text-xl font-black text-slate-800">{sec.name}</h3>
                <p className="text-slate-400 text-[10px] font-black uppercase mt-1">
                  {employees.filter(e => e.sectorId === sec.id).length} Colaboradores
                </p>
              </button>
            </div>
          ))}
        </div>

        {isAddingSector && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
                <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
                   <h3 className="font-black text-slate-800">Novo Setor</h3>
                   <button onClick={() => setIsAddingSector(false)}><X size={24} className="text-slate-300"/></button>
                </div>
                <form onSubmit={handleSaveSectorSubmit} className="p-6 space-y-4">
                   <input 
                     type="text" 
                     value={sectorName} 
                     onChange={e => setSectorName(e.target.value)} 
                     placeholder="Nome do Setor (Ex: Recepção)" 
                     className="w-full px-4 py-3 rounded-xl border-2 font-bold text-slate-800 outline-none focus:border-blue-400" 
                     required 
                   />
                   <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black text-xs uppercase shadow-lg">Criar Setor</button>
                </form>
             </div>
          </div>
        )}
      </div>
    );
  }

  if (viewMode === 'TODAY') {
    return (
      <div className="space-y-6 animate-in fade-in duration-500 pb-20">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex justify-between items-center">
          <div className="flex items-center space-x-4">
            <button onClick={() => setViewMode('LIST')} className="p-2 bg-slate-50 rounded-xl text-slate-400"><ChevronLeft size={20} /></button>
            <div>
              <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Escalados Hoje</h2>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{todayInfo.weekday} • {todayInfo.fullDate}</p>
            </div>
          </div>
          <div className="bg-slate-50 px-4 py-2 rounded-xl border">
             <span className="text-lg font-black text-slate-800">{scheduledToday.length}</span>
             <span className="ml-2 text-[9px] font-black text-slate-400 uppercase">Presentes</span>
          </div>
        </div>

        <div className="space-y-8">
           {(Object.entries(groupedBySector) as [string, Employee[]][]).sort().map(([sectorName, list]) => (
             <div key={sectorName} className="space-y-4">
                <div className="flex items-center space-x-2 px-2">
                   <Briefcase size={16} className="text-slate-400" />
                   <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">{sectorName} ({list.length})</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                   {list.map(emp => (
                     <div key={emp.id} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between group">
                        <div className="flex items-center space-x-4">
                           <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-md overflow-hidden ${emp.gender === 'F' ? 'bg-rose-400' : 'bg-blue-400'}`}>
                              {emp.photo ? (
                                <img src={emp.photo} alt={emp.name} className="w-full h-full object-cover" />
                              ) : (
                                <UserIcon size={20} className="text-white" />
                              )}
                           </div>
                           <div>
                              <p className="font-black text-slate-800 leading-none mb-1">{emp.name}</p>
                              <div className="flex items-center text-[9px] font-bold text-slate-400 uppercase tracking-tighter">
                                 <Clock size={10} className="mr-1" /> {emp.workingHours}
                              </div>
                           </div>
                        </div>
                     </div>
                   ))}
                </div>
             </div>
           ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="flex items-center space-x-3">
          <button onClick={() => onSelectSector(null)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-slate-600 transition-colors">
            <ChevronLeft size={20} />
          </button>
          <div>
            <h2 className="text-xl font-black text-slate-800 uppercase tracking-tighter">{currentSector?.name}</h2>
            <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">
                {viewMode === 'EXTRAS' ? `${filteredExtras.length} Profissionais` : `${filteredEmployees.length} Colaboradores`}
            </p>
          </div>
        </div>

        <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
          <button onClick={() => setViewMode('LIST')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'LIST' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Listagem</button>
          <button onClick={() => setViewMode('SCALE')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'SCALE' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Escala</button>
          <button onClick={() => setViewMode('EXTRAS')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'EXTRAS' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Extras</button>
        </div>

        {viewMode === 'EXTRAS' ? (
            <button onClick={() => setIsAddingExtra(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                <UserPlus size={18} /> <span className="hidden sm:inline">Cadastrar Extra</span>
            </button>
        ) : (
            <button onClick={() => setIsAddingEmployee(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                <UserPlus size={18} /> <span className="hidden sm:inline">Adicionar</span>
            </button>
        )}
      </div>

      {viewMode === 'LIST' && (
        <div className="space-y-4">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <input type="text" placeholder="Buscar colaborador..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 text-sm font-bold bg-white shadow-inner" />
          </div>

          <div className="grid grid-cols-1 gap-4">
            {filteredEmployees.map(emp => (
              <div key={emp.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row items-center gap-6 group hover:border-blue-200 transition-all">
                <div className="flex items-center space-x-4 flex-1">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-md overflow-hidden ${emp.gender === 'F' ? 'bg-rose-400' : 'bg-blue-400'}`}>
                    {emp.photo ? (
                      <img src={emp.photo} alt={emp.name} className="w-full h-full object-cover" />
                    ) : (
                      <UserIcon size={24} className="text-white" />
                    )}
                  </div>
                  <div>
                    <h4 className="font-black text-slate-800">{emp.name || 'Sem Nome'}</h4>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                       {emp.role} • {emp.scheduleType === 'Intermitente' ? 'Intermitente' : `Folga: ${emp.fixedDayOff || 'Rodízio'}`}
                    </p>
                  </div>
                </div>
                <div className="flex gap-4 items-center">
