import React, { useState, useRef, useMemo } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem, MaterialQuote } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  ChevronDown,
  ChevronUp,
  X,
  Clock,
  Layers,
  Wrench,
  Calculator,
  Edit2,
  User as UserIcon,
  CheckCircle2,
  Package,
  MessageSquare,
  TrendingDown,
  TrendingUp,
  DollarSign,
  Filter,
  Paperclip,
  FileText,
  Image as ImageIcon
