                       {scaleData.map(d => (
                          <th key={d.date} className={`border border-black p-1 w-8 text-center bg-slate-100 print:bg-gray-200 ${d.isSunday ? 'bg-gray-300 print:bg-gray-400' : ''}`}>
                             <div className="flex flex-col items-center justify-end h-24 text-black">
                                <span className="writing-mode-vertical rotate-180 text-[10px] font-bold uppercase tracking-widest mb-1 block" style={{writingMode: 'vertical-rl'}}>{d.weekdayFull}</span>
                                <span className="text-sm font-black border-t border-black w-full pt-1 block">{d.date}</span>
                             </div>
                          </th>
                       ))}
                    </tr>
                 </thead>
                 <tbody>
                    {scaleEmployees.map((emp, idx) => (
                       <tr key={emp.id} className={idx % 2 === 0 ? 'bg-white' : 'bg-slate-50 print:bg-white'}>
                          <td className="border border-black px-2 py-1 font-bold text-black uppercase text-[10px] whitespace-nowrap">{emp.name}</td>
                          <td className="border border-black px-1 py-1 text-center text-[9px] font-bold text-black">{emp.workingHours}</td>
                          {scaleData.map(d => {
                             const status = getShiftStatus(emp, d);
                             return (
                                <td key={d.date} className={`border border-black text-center font-black text-[10px] h-8 text-black ${d.isSunday ? 'bg-gray-200 print:bg-gray-300' : ''}`}>
                                   {status}
                                </td>
                             );
                          })}
                       </tr>
                    ))}
                 </tbody>
              </table>

              {/* FOOTER DA PLANILHA */}
              <div className="mt-6 flex flex-col md:flex-row gap-4 print:flex-row">
                 <div className="w-full md:w-1/3 border-2 border-black text-black">
                    <div className="bg-gray-200 border-b border-black p-1 text-center font-black uppercase text-xs">Legenda</div>
                    <div className="p-2 space-y-1 text-[10px] font-bold uppercase">
                       <div className="flex justify-between border-b border-gray-300 pb-1"><span>F</span> <span>Folga</span></div>
                       <div className="flex justify-between border-b border-gray-300 pb-1"><span>D</span> <span>Domingo</span></div>
                       <div className="flex justify-between border-b border-gray-300 pb-1"><span>FE</span> <span>Férias</span></div>
                       <div className="flex justify-between"><span>AT</span> <span>Atestado</span></div>
                    </div>
                 </div>
                 <div className="w-full md:w-2/3 border-2 border-black flex flex-col text-black">
                    <div className="bg-gray-200 border-b border-black p-1 text-center font-black uppercase text-xs">Observações Gerais</div>
                    <div className="flex-1 p-2">
                       {/* Linhas pautadas para obs */}
                       <div className="border-b border-black h-6 mb-2"></div>
                       <div className="border-b border-black h-6 mb-2"></div>
                       <div className="border-b border-black h-6 mb-2"></div>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="flex items-center space-x-3">
          <button onClick={() => onSelectSector(null)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-slate-600 transition-colors">
            <ChevronLeft size={20} />
          </button>
          <div>
            <h2 className="text-xl font-black text-slate-800 uppercase tracking-tighter">{currentSector?.name}</h2>
            <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">
                {viewMode === 'EXTRAS' ? `${filteredExtras.length} Profissionais` : `${filteredEmployees.length} Colaboradores`}
            </p>
          </div>
        </div>

        <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
          <button onClick={() => setViewMode('LIST')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'LIST' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Listagem</button>
          <button onClick={() => setViewMode('SCALE')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'SCALE' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Escala</button>
          <button onClick={() => setViewMode('EXTRAS')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'EXTRAS' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Extras</button>
        </div>

        {viewMode === 'EXTRAS' ? (
            <button onClick={() => setIsAddingExtra(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                <UserPlus size={18} /> <span className="hidden sm:inline">Cadastrar Extra</span>
            </button>
        ) : (
            <button onClick={() => setIsAddingEmployee(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                <UserPlus size={18} /> <span className="hidden sm:inline">Adicionar</span>
            </button>
