};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    currentView: ViewType.DASHBOARD,
    currentHotel: 'VILLAGE',
    hotels: {
      VILLAGE: { ...INITIAL_HOTEL_DATA },
      GOLDEN_PARK: { ...INITIAL_HOTEL_DATA },
      THERMAL_RESORT: { ...INITIAL_HOTEL_DATA }
    },
    selectedFloor: null,
    selectedApartmentId: null,
    selectedSectorId: null,
    integrations: [{ id: '1', name: 'Global Sync', type: 'Spreadsheet', status: 'Disconnected' }],
    currentUser: null
  });

  const [isRefreshing, setIsRefreshing] = useState(false);

  const currentHotelData = state.hotels[state.currentHotel];
  const theme = themes[state.currentHotel];

  const fetchHotelData = useCallback(async (hotel: HotelType) => {
    const integration = state.integrations[0];
    if (!integration || !integration.url) return;

    try {
      setIsRefreshing(true);
      const response = await fetch(`${integration.url}?hotel=${hotel}`);
      const json = await response.json();

      if (json.status === 'success') {
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [hotel]: json.data
          }
        }));
      }
    } catch (error) {
      console.error("Fetch error:", error);
    } finally {
      setIsRefreshing(false);
    }
  }, [state.integrations]);

  const syncToSheet = async (dataType: string, data: any, newFiles?: any[]) => {
    const integration = state.integrations[0];
    if (!integration || !integration.url) {
      console.warn("No integration URL configured");
      return;
    }

    try {
      setIsRefreshing(true);
      const payload = {
        hotel: state.currentHotel,
        dataType,
        ...data,
        newFiles
      };

      await fetch(integration.url, {
        method: 'POST',
        body: JSON.stringify(payload)
      });

      // Refresh data after sync (optional delay to allow processing)
      setTimeout(() => fetchHotelData(state.currentHotel), 2000);
    } catch (error) {
      console.error("Sync failed", error);
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, currentUser: user }));
    if (user.hotel) {
      setState(prev => ({ ...prev, currentHotel: user.hotel! }));
      fetchHotelData(user.hotel!);
    } else {
      fetchHotelData(state.currentHotel);
    }
  };

  const handleSaveEmployee = (emp: Employee, newFiles?: any[]) => {
    const existing = currentHotelData.employees.find(e => e.id === emp.id);
    const newEmps = existing 
      ? currentHotelData.employees.map(e => e.id === emp.id ? emp : e)
      : [...currentHotelData.employees, emp];

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], employees: newEmps }
      }
    }));

    // Create a payload copy for sync
    const payloadEmp = { ...emp };
    if (newFiles && newFiles.length > 0) {
      payloadEmp.photo = '';
    }

    syncToSheet('EMPLOYEE', payloadEmp, newFiles);
