import React, { useState, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import Login from './components/Login';
import BottomNav from './components/BottomNav';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import SettingsView from './components/SettingsView';
import InventoryView from './components/InventoryView';
import ReportsView from './components/ReportsView';
import TodayScheduleView from './components/TodayScheduleView';

import { 
  AppState, 
  HotelType, 
  ViewType, 
  User, 
  HotelData, 
  Apartment, 
  Budget, 
  Employee, 
  Sector, 
  InventoryItem, 
  InventoryOperation, 
  Supplier, 
  Integration,
  HotelTheme
} from './types';

const themes: Record<HotelType, HotelTheme> = {
  VILLAGE: { primary: '#10b981', secondary: '#3b82f6', accent: '#f59e0b', bg: '#f1f5f9', text: '#1e293b', chartColors: ['#10b981', '#3b82f6', '#f59e0b', '#ef4444'] },
  GOLDEN_PARK: { primary: '#f59e0b', secondary: '#3b82f6', accent: '#10b981', bg: '#fffbeb', text: '#1e293b', chartColors: ['#f59e0b', '#3b82f6', '#10b981', '#ef4444'] },
  THERMAL_RESORT: { primary: '#3b82f6', secondary: '#10b981', accent: '#f59e0b', bg: '#eff6ff', text: '#1e293b', chartColors: ['#3b82f6', '#10b981', '#f59e0b', '#ef4444'] }
};

const INITIAL_HOTEL_DATA: HotelData = {
  apartments: {},
  budgets: [],
  employees: [],
  extras: [],
  sectors: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  config: { showSuppliersTab: true }
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    currentView: ViewType.DASHBOARD,
    currentHotel: 'VILLAGE',
    hotels: {
      VILLAGE: { ...INITIAL_HOTEL_DATA },
      GOLDEN_PARK: { ...INITIAL_HOTEL_DATA },
      THERMAL_RESORT: { ...INITIAL_HOTEL_DATA }
    },
    selectedFloor: null,
    selectedApartmentId: null,
    selectedSectorId: null,
    integrations: [{ id: '1', name: 'Global Sync', type: 'Spreadsheet', status: 'Disconnected' }],
    currentUser: null
  });

  const [isRefreshing, setIsRefreshing] = useState(false);

  const currentHotelData = state.hotels[state.currentHotel];
  const theme = themes[state.currentHotel];

  const fetchHotelData = useCallback(async (hotel: HotelType) => {
    const integration = state.integrations[0];
    if (!integration || !integration.url) return;

    try {
      setIsRefreshing(true);
      const response = await fetch(`${integration.url}?hotel=${hotel}`);
      const json = await response.json();

      if (json.status === 'success') {
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [hotel]: json.data
          }
        }));
      }
    } catch (error) {
      console.error("Fetch error:", error);
    } finally {
      setIsRefreshing(false);
    }
  }, [state.integrations]);

  const syncToSheet = async (dataType: string, data: any, newFiles?: any[]) => {
    const integration = state.integrations[0];
    if (!integration || !integration.url) {
      console.warn("No integration URL configured");
      return;
    }

    try {
      setIsRefreshing(true);
      const payload = {
        hotel: state.currentHotel,
        dataType,
        ...data,
        newFiles
      };

      await fetch(integration.url, {
        method: 'POST',
        body: JSON.stringify(payload)
      });

      // Refresh data after sync (optional delay to allow processing)
      setTimeout(() => fetchHotelData(state.currentHotel), 2000);
    } catch (error) {
      console.error("Sync failed", error);
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, currentUser: user }));
    if (user.hotel) {
      setState(prev => ({ ...prev, currentHotel: user.hotel! }));
      fetchHotelData(user.hotel!);
    } else {
      fetchHotelData(state.currentHotel);
    }
  };

  const handleSaveEmployee = (emp: Employee, newFiles?: any[]) => {
    const existing = currentHotelData.employees.find(e => e.id === emp.id);
    const newEmps = existing 
      ? currentHotelData.employees.map(e => e.id === emp.id ? emp : e)
      : [...currentHotelData.employees, emp];

    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], employees: newEmps }
      }
    }));

    // Create a payload copy for sync
    // If we are uploading a new file (newFiles is present), we clear the 'photo' field in the payload
    // to avoid sending the large base64 string. The server script will populate the correct Drive URL 
    // from the uploaded file independently.
    const payloadEmp = { ...emp };
    if (newFiles && newFiles.length > 0) {
      payloadEmp.photo = '';
    }

    syncToSheet('EMPLOYEE', payloadEmp, newFiles);
  };

  const handleDeleteEmployee = (id: string) => {
    const newEmps = currentHotelData.employees.filter(e => e.id !== id);
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], employees: newEmps }
      }
    }));
    syncToSheet('DELETE', { id, targetType: 'EMPLOYEE' });
  };

  const handleSaveBudget = (budget: Budget, newFiles?: any[]) => {
     const existing = currentHotelData.budgets.find(b => b.id === budget.id);
     const newBudgets = existing
       ? currentHotelData.budgets.map(b => b.id === budget.id ? budget : b)
       : [...currentHotelData.budgets, budget];

     setState(prev => ({
       ...prev,
       hotels: {
         ...prev.hotels,
         [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], budgets: newBudgets }
       }
     }));

     syncToSheet('BUDGET', budget, newFiles);
  };

  const handleDeleteBudget = (id: string) => {
     const newBudgets = currentHotelData.budgets.filter(b => b.id !== id);
     setState(prev => ({
       ...prev,
       hotels: {
         ...prev.hotels,
         [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], budgets: newBudgets }
       }
     }));
     syncToSheet('DELETE', { id, targetType: 'BUDGET' });
  };

  const handleSaveApartment = (apt: Apartment, newFiles?: any[]) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
           ...prev.hotels[prev.currentHotel],
           apartments: { ...prev.hotels[prev.currentHotel].apartments, [apt.id]: apt }
        }
      }
    }));
    syncToSheet('APARTMENT', apt, newFiles);
  };

  const handleSaveInventory = (item: InventoryItem) => {
     const existing = currentHotelData.inventory.find(i => i.id === item.id);
     const newInv = existing
       ? currentHotelData.inventory.map(i => i.id === item.id ? item : i)
       : [...currentHotelData.inventory, item];

     setState(prev => ({
       ...prev,
       hotels: {
         ...prev.hotels,
         [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], inventory: newInv }
       }
     }));
     syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventory = (id: string) => {
     const newInv = currentHotelData.inventory.filter(i => i.id !== id);
     setState(prev => ({
       ...prev,
       hotels: {
         ...prev.hotels,
         [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], inventory: newInv }
       }
     }));
     syncToSheet('DELETE', { id, targetType: 'INVENTORY' });
  };

  const handleInventoryOperation = (op: InventoryOperation) => {
     // Update history
     const newHistory = [op, ...currentHotelData.inventoryHistory];

     // Update item quantity
     const item = currentHotelData.inventory.find(i => i.id === op.itemId);
     if (item) {
        const newQty = op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity;
        const newItem = { ...item, quantity: newQty, lastUpdate: Date.now() };
        handleSaveInventory(newItem); // Save item updates quantity
     }

     setState(prev => ({
       ...prev,
       hotels: {
         ...prev.hotels,
         [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], inventoryHistory: newHistory }
       }
     }));
     syncToSheet('INVENTORY_OP', op);
  };

  const handleSaveSupplier = (s: Supplier) => {
      const existing = currentHotelData.suppliers.find(sup => sup.id === s.id);
      const newSup = existing 
         ? currentHotelData.suppliers.map(sup => sup.id === s.id ? s : sup)
         : [...currentHotelData.suppliers, s];

      setState(prev => ({
         ...prev,
         hotels: {
           ...prev.hotels,
           [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], suppliers: newSup }
         }
      }));
      syncToSheet('SUPPLIER', s);
  };

  const handleDeleteSupplier = (id: string) => {
     const newSup = currentHotelData.suppliers.filter(s => s.id !== id);
     setState(prev => ({
        ...prev,
        hotels: {
           ...prev.hotels,
           [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], suppliers: newSup }
        }
     }));
     syncToSheet('DELETE', { id, targetType: 'SUPPLIER' });
  };

  const handleSaveSector = (s: Sector) => {
     const existing = currentHotelData.sectors.find(sec => sec.id === s.id);
     const newSectors = existing 
       ? currentHotelData.sectors.map(sec => sec.id === s.id ? s : sec)
       : [...currentHotelData.sectors, s];

     setState(prev => ({
       ...prev,
       hotels: {
         ...prev.hotels,
         [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], sectors: newSectors }
       }
     }));
     syncToSheet('SECTOR', s);
  };

  const handleDeleteSector = (id: string) => {
     const newSectors = currentHotelData.sectors.filter(s => s.id !== id);
     setState(prev => ({
       ...prev,
       hotels: {
         ...prev.hotels,
         [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], sectors: newSectors }
       }
     }));
     syncToSheet('DELETE', { id, targetType: 'SECTOR' });
  };

  const handleUpdateConfig = (config: any) => {
     setState(prev => ({
       ...prev,
       hotels: {
         ...prev.hotels,
         [prev.currentHotel]: { 
            ...prev.hotels[prev.currentHotel], 
            config: { ...prev.hotels[prev.currentHotel].config, ...config }
         }
       }
     }));
     syncToSheet('CONFIG', config);
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} onFetchHotelData={fetchHotelData} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-900">
      <Sidebar 
        currentView={state.currentView} 
        onViewChange={(v) => setState(prev => ({ ...prev, currentView: v, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }))}
        currentHotel={state.currentHotel}
        onHotelChange={(h) => { setState(prev => ({ ...prev, currentHotel: h })); fetchHotelData(h); }}
        onLogout={() => setState(prev => ({ ...prev, currentUser: null }))}
        theme={theme}
        role={state.currentUser.role}
      />

      <main className="flex-1 md:ml-64 p-4 md:p-8 overflow-y-auto h-screen">
        <div className="max-w-7xl mx-auto">

          {state.currentView === ViewType.DASHBOARD && (
             <Dashboard 
               apartments={currentHotelData.apartments}
               employees={currentHotelData.employees}
               inventory={currentHotelData.inventory}
               sectors={currentHotelData.sectors}
               theme={theme}
               lastSync={Date.now()} // Simplified
               onRefresh={() => fetchHotelData(state.currentHotel)}
               isRefreshing={isRefreshing}
             />
          )}

          {state.currentView === ViewType.APARTMENTS && !state.selectedFloor && (
             <ApartmentsView 
                onSelectFloor={(f) => setState(prev => ({ ...prev, selectedFloor: f }))} 
                theme={theme}
                hotelName={state.currentHotel.replace('_', ' ')}
             />
          )}

          {state.currentView === ViewType.APARTMENTS && state.selectedFloor && !state.selectedApartmentId && (
             <FloorDetailView 
                floor={state.selectedFloor}
                apartments={currentHotelData.apartments}
                theme={theme}
                onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))}
                onSelectApartment={(id) => setState(prev => ({ ...prev, selectedApartmentId: id }))}
             />
          )}

          {state.currentView === ViewType.APARTMENTS && state.selectedApartmentId && (
            <ApartmentDetailView 
               apartment={currentHotelData.apartments[state.selectedApartmentId] || { 
                 id: state.selectedApartmentId, 
                 roomNumber: parseInt(state.selectedApartmentId.split('-')[1]), 
                 floor: parseInt(state.selectedApartmentId.split('-')[0]), 
                 defects: [] 
               }}
               theme={theme}
               onBack={() => setState(prev => ({ ...prev, selectedApartmentId: null }))}
               onSave={handleSaveApartment}
            />
          )}

          {state.currentView === ViewType.BUDGETS && (
             <BudgetsView 
               budgets={currentHotelData.budgets} 
               theme={theme}
               onSave={handleSaveBudget}
               onDelete={handleDeleteBudget}
             />
          )}

          {state.currentView === ViewType.EMPLOYEES && (
             <EmployeesView 
               employees={currentHotelData.employees}
               sectors={currentHotelData.sectors}
               theme={theme}
               onSave={handleSaveEmployee}
               onDelete={handleDeleteEmployee}
               onSaveSector={handleSaveSector}
               onDeleteSector={handleDeleteSector}
             />
          )}

          {state.currentView === ViewType.INVENTORY && (
             <InventoryView 
               inventory={currentHotelData.inventory}
               history={currentHotelData.inventoryHistory}
               suppliers={currentHotelData.suppliers}
               employees={currentHotelData.employees}
               sectors={currentHotelData.sectors}
               showSuppliersTab={currentHotelData.config?.showSuppliersTab}
               theme={theme}
               onSave={handleSaveInventory}
               onDelete={handleDeleteInventory}
               onOperation={handleInventoryOperation}
               onSaveSupplier={handleSaveSupplier}
               onDeleteSupplier={handleDeleteSupplier}
               onSaveSector={handleSaveSector}
               onDeleteSector={handleDeleteSector}
               role={state.currentUser.role}
               currentUser={state.currentUser.name}
             />
          )}

          {state.currentView === ViewType.REPORTS && (
             <ReportsView 
               apartments={currentHotelData.apartments}
               theme={theme}
               onSelectApartment={(id) => {
                 setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedFloor: parseInt(id.split('-')[0]), selectedApartmentId: id }));
               }}
             />
          )}

          {state.currentView === ViewType.TODAY_SCHEDULE && (
             <TodayScheduleView 
               employees={currentHotelData.employees}
               theme={theme}
             />
          )}

          {state.currentView === ViewType.SETTINGS && (
             <SettingsView 
               integrations={state.integrations}
               theme={theme}
               hotelConfig={currentHotelData.config}
               suppliers={currentHotelData.suppliers}
               onSaveSupplier={handleSaveSupplier}
               onDeleteSupplier={handleDeleteSupplier}
               onUpdateConfig={handleUpdateConfig}
               onUpdate={(int) => setState(prev => ({ ...prev, integrations: [int] }))}
             />
          )}
        </div>
      </main>

      <BottomNav 
         currentView={state.currentView}
         onViewChange={(v) => setState(prev => ({ ...prev, currentView: v }))}
         theme={theme}
         role={state.currentUser.role}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { Employee, Sector, HotelTheme, UniformItem } from '../types';
import { 
  Users, 
  Search, 
  Plus, 
  Filter, 
  X, 
  Camera, 
  Briefcase, 
  Phone, 
  Calendar, 
  DollarSign,
  User as UserIcon, 
  Trash2, 
  Edit2, 
  ChevronRight, 
  PlusCircle, 
  Shirt, 
  CalendarDays
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  sectors: Sector[];
  theme: HotelTheme;
  onSave: (emp: Employee, files?: any[]) => void;
  onDelete: (id: string) => void;
  onSaveSector?: (sector: Sector) => void;
  onDeleteSector?: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  sectors, 
  theme, 
  onSave, 
  onDelete, 
  onSaveSector, 
  onDeleteSector 
}) => {
  const [activeTab, setActiveTab] = useState<'LISTA' | 'SETORES'>('LISTA');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedSectorId, setSelectedSectorId] = useState<string | null>(null);

  // Modal states
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [sectorName, setSectorName] = useState('');

  // Employee Form State
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [gender, setGender] = useState<'M' | 'F'>('M');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState('');
  const [salary, setSalary] = useState('');
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('');
  const [fixedDayOff, setFixedDayOff] = useState('');
  const [sundayOffs, setSundayOffs] = useState<number[]>([]);
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);

  // Photo State
  const [photoPreview, setPhotoPreview] = useState<string>('');
  const [newPhotoFile, setNewPhotoFile] = useState<{data: string, mimeType: string, fileName: string} | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetEmployeeForm = () => {
    setName(''); setRole(''); setGender('M'); setContact(''); setStartDate(''); setSalary(''); 
    setScheduleType('6x1'); setShiftType('Par'); setWorkingHours(''); setFixedDayOff(''); 
    setSundayOffs([]); setVacationStatus('Pendente'); setUniforms([]);
    setPhotoPreview(''); setNewPhotoFile(null);
    setEditingEmployee(null); setIsAddingEmployee(false);
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name);
    setRole(emp.role);
    setGender(emp.gender);
    setContact(emp.contact);
    setStartDate(emp.startDate);
    setSalary(emp.salary.toString());
    setScheduleType(emp.scheduleType);
    setShiftType(emp.shiftType || 'Par');
    setWorkingHours(emp.workingHours);
    setFixedDayOff(emp.fixedDayOff);
    setSundayOffs(emp.sundayOffs || []);
    setVacationStatus(emp.vacationStatus);
    setUniforms(emp.uniforms || []);
    setPhotoPreview(emp.photo || '');
    setNewPhotoFile(null);
    setSelectedSectorId(emp.sectorId);
    setIsAddingEmployee(true);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const fullBase64 = reader.result?.toString() || '';
        const base64Data = fullBase64.split(',')[1] || '';
        setPhotoPreview(fullBase64);
        setNewPhotoFile({ data: base64Data, mimeType: file.type, fileName: file.name });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId && !editingEmployee?.sectorId) return;

    // Use the new photo preview if a file was uploaded, otherwise keep the existing photo
    const photoToSave = (newPhotoFile && photoPreview) ? photoPreview : (editingEmployee?.photo || '');

    const finalSectorId = selectedSectorId || editingEmployee?.sectorId || '';
    const departmentName = sectors.find(s => s.id === finalSectorId)?.name || '';

    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', 
      role: role || 'Cargo', 
      gender, 
      contact, 
      startDate,
      salary: parseFloat(salary) || 0, 
      department: departmentName,
      sectorId: finalSectorId, 
      status: 'Ativo', 
      scheduleType, 
      shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours: scheduleType === 'Intermitente' ? '' : workingHours, 
      fixedDayOff: scheduleType === '6x1' ? fixedDayOff : '', 
      sundayOffs: scheduleType === '6x1' ? sundayOffs : [], 
      weeklyDayOff: scheduleType === '6x1' ? fixedDayOff : '', 
      monthlySundayOff: '', 
      vacationStatus, 
      uniforms,
      photo: photoToSave
    };

    // Pass newPhotoFile as an array to syncToSheet via onSave
    onSave(newEmp, newPhotoFile ? [newPhotoFile] : undefined);
    resetEmployeeForm();
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSaveSector) {
      onSaveSector({ id: Date.now().toString(), name: sectorName, standardUniform: [] });
      setSectorName('');
      setIsAddingSector(false);
    }
  };

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => 
      (selectedSectorId ? e.sectorId === selectedSectorId : true) &&
      (e.name.toLowerCase().includes(searchTerm.toLowerCase()) || e.role.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [employees, selectedSectorId, searchTerm]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm w-full md:w-auto">
          <button onClick={() => { setActiveTab('LISTA'); setSelectedSectorId(null); }} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'LISTA' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>
            Colaboradores
          </button>
          <button onClick={() => setActiveTab('SETORES')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'SETORES' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>
            Setores
          </button>
        </div>

        {activeTab === 'LISTA' && (
          <div className="flex gap-3 w-full md:w-auto">
            <div className="relative flex-1 md:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
              <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 outline-none text-xs font-bold bg-white" />
            </div>
            {selectedSectorId && (
              <button onClick={() => setIsAddingEmployee(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                <Plus size={18} /> <span>Novo</span>
              </button>
            )}
          </div>
        )}
      </div>

      {activeTab === 'SETORES' ? (
        <div className="space-y-6">
           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              <button onClick={() => setIsAddingSector(true)} className="bg-white border-2 border-dashed border-slate-200 hover:border-blue-300 h-40 rounded-[2rem] flex flex-col items-center justify-center text-slate-400 hover:text-blue-500 transition-all group">
                 <PlusCircle size={32} className="mb-2 group-hover:scale-110 transition-transform"/>
                 <span className="font-bold text-xs uppercase">Novo Setor</span>
              </button>
              {sectors.map(sec => (
                 <div key={sec.id} className="relative group">
                    {onDeleteSector && (
                      <button onClick={() => onDeleteSector(sec.id)} className="absolute top-4 right-4 z-10 p-2 bg-white/80 hover:bg-white text-slate-300 hover:text-rose-500 rounded-full shadow-sm opacity-0 group-hover:opacity-100 transition-all">
                         <Trash2 size={16}/>
                      </button>
                    )}
                    <button onClick={() => { setSelectedSectorId(sec.id); setActiveTab('LISTA'); }} className="w-full bg-white h-40 rounded-[2rem] border border-slate-50 shadow-sm hover:shadow-xl transition-all flex flex-col items-center justify-center p-6">
                       <Briefcase size={28} className="text-slate-300 mb-3" />
                       <h3 className="text-lg font-black text-slate-800">{sec.name}</h3>
                       <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">{employees.filter(e => e.sectorId === sec.id).length} Colaboradores</p>
                    </button>
                 </div>
              ))}
           </div>
        </div>
      ) : (
        <div className="space-y-6">
           {selectedSectorId && (
              <div className="flex items-center space-x-2 text-slate-400 font-bold text-xs">
                 <button onClick={() => { setSelectedSectorId(null); setActiveTab('SETORES'); }}>Setores</button>
                 <ChevronRight size={14}/>
                 <span className="text-slate-800">{sectors.find(s => s.id === selectedSectorId)?.name}</span>
              </div>
           )}

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredEmployees.map(emp => (
                 <div key={emp.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-lg transition-all group relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-24 bg-gradient-to-b from-slate-50 to-transparent"></div>
                    <div className="relative flex flex-col items-center text-center space-y-3">
                       <div className="w-20 h-20 rounded-[1.5rem] shadow-xl overflow-hidden border-4 border-white">
                          {emp.photo ? (
                             <img src={emp.photo} alt={emp.name} className="w-full h-full object-cover"/>
                          ) : (
                             <div className={`w-full h-full flex items-center justify-center text-2xl font-black text-white ${emp.gender === 'F' ? 'bg-rose-300' : 'bg-blue-300'}`}>
                                {emp.name[0]}
                             </div>
                          )}
                       </div>
                       <div>
                          <h3 className="text-lg font-black text-slate-800 leading-tight">{emp.name}</h3>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">{emp.role}</p>
                       </div>
                    </div>

                    <div className="mt-6 pt-6 border-t border-slate-50 grid grid-cols-2 gap-4">
                       <div className="space-y-1">
                          <p className="text-[9px] font-black text-slate-300 uppercase flex items-center"><Phone size={10} className="mr-1"/> Contato</p>
                          <p className="text-xs font-bold text-slate-600 truncate">{emp.contact || 'N/A'}</p>
                       </div>
                       <div className="space-y-1 text-right">
                          <p className="text-[9px] font-black text-slate-300 uppercase flex items-center justify-end"><DollarSign size={10} className="mr-1"/> Salário</p>
                          <p className="text-xs font-bold text-slate-600">R$ {emp.salary.toLocaleString('pt-BR')}</p>
                       </div>
                       <div className="space-y-1">
                          <p className="text-[9px] font-black text-slate-300 uppercase flex items-center"><Calendar size={10} className="mr-1"/> Admissão</p>
                          <p className="text-xs font-bold text-slate-600">{emp.startDate ? new Date(emp.startDate).toLocaleDateString() : 'N/A'}</p>
                       </div>
                       <div className="space-y-1 text-right">
                          <p className="text-[9px] font-black text-slate-300 uppercase flex items-center justify-end"><CalendarDays size={10} className="mr-1"/> Escala</p>
                          <p className="text-xs font-bold text-slate-600">{emp.scheduleType}</p>
                       </div>
                    </div>

                    <div className="mt-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                       <button onClick={() => handleEditEmployee(emp)} className="flex-1 py-2 bg-slate-50 text-slate-600 rounded-xl font-black text-[10px] uppercase hover:bg-blue-50 hover:text-blue-500 transition-colors flex items-center justify-center space-x-1">
                          <Edit2 size={12} /> <span>Editar</span>
                       </button>
                       <button onClick={() => onDelete(emp.id)} className="flex-1 py-2 bg-slate-50 text-slate-600 rounded-xl font-black text-[10px] uppercase hover:bg-rose-50 hover:text-rose-500 transition-colors flex items-center justify-center space-x-1">
                          <Trash2 size={12} /> <span>Excluir</span>
                       </button>
                    </div>
                 </div>
              ))}
              {filteredEmployees.length === 0 && (
                 <div className="col-span-full py-20 text-center">
                    <p className="text-slate-300 font-bold italic">Nenhum colaborador encontrado.</p>
                 </div>
              )}
           </div>
        </div>
      )}

      {/* Modal ADD SECTOR */}
      {isAddingSector && (
         <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
                <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
                   <h3 className="font-black text-slate-800">Novo Setor</h3>
                   <button onClick={() => setIsAddingSector(false)}><X size={24} className="text-slate-300"/></button>
                </div>
                <form onSubmit={handleSaveSectorSubmit} className="p-6 space-y-4">
                   <input type="text" value={sectorName} onChange={e => setSectorName(e.target.value)} placeholder="Nome do Setor" className="w-full px-4 py-3 rounded-xl border-2 font-bold text-slate-800 outline-none focus:border-blue-400" required />
                   <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black text-xs uppercase shadow-lg">Criar Setor</button>
                </form>
             </div>
          </div>
      )}

      {/* Modal ADD/EDIT EMPLOYEE */}
      {isAddingEmployee && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden max-h-[90vh] flex flex-col">
              <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                 <div>
                    <h2 className="text-xl font-black text-slate-800">{editingEmployee ? 'Editar Colaborador' : 'Novo Colaborador'}</h2>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{sectors.find(s => s.id === selectedSectorId)?.name}</p>
                 </div>
                 <button onClick={resetEmployeeForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveEmployeeSubmit} className="p-8 overflow-y-auto space-y-6">
                 <div className="flex flex-col items-center mb-6">
                    <div className="relative w-24 h-24 rounded-[2rem] bg-slate-100 overflow-hidden border-4 border-white shadow-lg cursor-pointer hover:brightness-95 transition-all" onClick={() => fileInputRef.current?.click()}>
                       {photoPreview ? (
                          <img src={photoPreview} alt="Preview" className="w-full h-full object-cover" />
                       ) : (
                          <div className="w-full h-full flex flex-col items-center justify-center text-slate-300">
                             <Camera size={24} />
                             <span className="text-[8px] font-black uppercase mt-1">Foto</span>
                          </div>
                       )}
                    </div>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*" />
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <div className="col-span-2">
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Nome Completo</label>
                       <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold text-slate-800" required />
                    </div>
                    <div>
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Cargo / Função</label>
                       <input type="text" value={role} onChange={e => setRole(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold text-slate-800" required />
                    </div>
                    <div>
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Gênero</label>
                       <div className="flex bg-slate-50 p-1 rounded-xl">
                          <button type="button" onClick={() => setGender('M')} className={`flex-1 py-2 rounded-lg text-xs font-black uppercase transition-all ${gender === 'M' ? 'bg-white shadow-sm text-blue-500' : 'text-slate-400'}`}>Masc</button>
                          <button type="button" onClick={() => setGender('F')} className={`flex-1 py-2 rounded-lg text-xs font-black uppercase transition-all ${gender === 'F' ? 'bg-white shadow-sm text-rose-500' : 'text-slate-400'}`}>Fem</button>
                       </div>
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <div>
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Contato</label>
                       <input type="text" value={contact} onChange={e => setContact(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold text-slate-800" placeholder="(00) 00000-0000" />
                    </div>
                    <div>
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Salário</label>
                       <input type="number" value={salary} onChange={e => setSalary(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold text-slate-800" placeholder="R$ 0,00" />
                    </div>
                 </div>

                 <div className="p-6 bg-slate-50 rounded-[2rem] space-y-4">
                    <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Detalhes da Escala</h3>
                    <div className="grid grid-cols-2 gap-4">
                        <select value={scheduleType} onChange={e => setScheduleType(e.target.value as any)} className="w-full px-4 py-3 rounded-xl border border-slate-200 outline-none font-bold text-slate-800 bg-white">
                           <option value="6x1">Escala 6x1</option>
                           <option value="12x36">Escala 12x36</option>
                           <option value="Intermitente">Intermitente</option>
                        </select>
                        <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 outline-none font-bold text-slate-800 bg-white" />
                    </div>

                    {scheduleType === '6x1' && (
                       <div className="space-y-4 animate-in fade-in">
                          <div>
                             <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Folga Fixa Semanal</label>
                             <div className="grid grid-cols-4 gap-2">
                                {['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'].map(d => (
                                   <button key={d} type="button" onClick={() => setFixedDayOff(d)} className={`py-2 rounded-lg text-[10px] font-black border uppercase transition-all ${fixedDayOff === d ? 'bg-slate-800 text-white border-slate-800' : 'bg-white border-slate-200 text-slate-400'}`}>{d.substr(0, 3)}</button>
                                ))}
                             </div>
                          </div>
                          <div>
                             <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Domingos de Folga (no mês)</label>
                             <div className="flex gap-2">
                                {[1, 2, 3, 4, 5].map(n => (
                                   <button key={n} type="button" onClick={() => {
                                      if (sundayOffs.includes(n)) setSundayOffs(sundayOffs.filter(i => i !== n));
                                      else setSundayOffs([...sundayOffs, n]);
                                   }} className={`w-10 h-10 rounded-lg font-black border transition-all ${sundayOffs.includes(n) ? 'bg-blue-500 text-white border-blue-500' : 'bg-white border-slate-200 text-slate-400'}`}>{n}º</button>
                                ))}
                             </div>
                          </div>
                       </div>
                    )}
                 </div>

                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 hover:brightness-110" style={{ backgroundColor: theme.primary }}>Salvar Colaborador</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default EmployeesView;

import React, { useState, useRef, useMemo } from 'react';
import { Employee, Sector, HotelTheme, UniformItem } from '../types';
import { 
  Users, 
  Search, 
  Plus, 
  Filter, 
  X, 
  Camera, 
  Briefcase, 
  Phone, 
  Calendar, 
  DollarSign,
  User as UserIcon, 
  Trash2, 
  Edit2, 
  ChevronRight, 
  PlusCircle, 
  Shirt, 
  CalendarDays
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  sectors: Sector[];
  theme: HotelTheme;
  onSave: (emp: Employee, files?: any[]) => void;
  onDelete: (id: string) => void;
  onSaveSector?: (sector: Sector) => void;
  onDeleteSector?: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  sectors, 
  theme, 
  onSave, 
  onDelete, 
  onSaveSector, 
  onDeleteSector 
}) => {
  const [activeTab, setActiveTab] = useState<'LISTA' | 'SETORES'>('LISTA');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedSectorId, setSelectedSectorId] = useState<string | null>(null);

  // Modal states
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [sectorName, setSectorName] = useState('');

  // Employee Form State
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [gender, setGender] = useState<'M' | 'F'>('M');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState('');
  const [salary, setSalary] = useState('');
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('');
  const [fixedDayOff, setFixedDayOff] = useState('');
  const [sundayOffs, setSundayOffs] = useState<number[]>([]);
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);

  // Photo State
  const [photoPreview, setPhotoPreview] = useState<string>('');
  const [newPhotoFile, setNewPhotoFile] = useState<{data: string, mimeType: string, fileName: string} | null>(null);
  const [isPhotoRemoved, setIsPhotoRemoved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetEmployeeForm = () => {
    setName(''); setRole(''); setGender('M'); setContact(''); setStartDate(''); setSalary(''); 
    setScheduleType('6x1'); setShiftType('Par'); setWorkingHours(''); setFixedDayOff(''); 
    setSundayOffs([]); setVacationStatus('Pendente'); setUniforms([]);
    setPhotoPreview(''); setNewPhotoFile(null); setIsPhotoRemoved(false);
    setEditingEmployee(null); setIsAddingEmployee(false);
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name);
    setRole(emp.role);
    setGender(emp.gender);
    setContact(emp.contact);
    setStartDate(emp.startDate);
    setSalary(emp.salary.toString());
    setScheduleType(emp.scheduleType);
    setShiftType(emp.shiftType || 'Par');
    setWorkingHours(emp.workingHours);
    setFixedDayOff(emp.fixedDayOff);
    setSundayOffs(emp.sundayOffs || []);
    setVacationStatus(emp.vacationStatus);
    setUniforms(emp.uniforms || []);
    setPhotoPreview(emp.photo || '');
    setNewPhotoFile(null);
    setIsPhotoRemoved(false);
    setSelectedSectorId(emp.sectorId);
    setIsAddingEmployee(true);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const fullBase64 = reader.result?.toString() || '';
        const base64Data = fullBase64.split(',')[1] || '';
        setPhotoPreview(fullBase64);
        setNewPhotoFile({ data: base64Data, mimeType: file.type, fileName: file.name });
        setIsPhotoRemoved(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemovePhoto = () => {
    setPhotoPreview('');
    setNewPhotoFile(null);
    setIsPhotoRemoved(true);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId && !editingEmployee?.sectorId) return;

    // Determine final photo state
    // If isPhotoRemoved is true, we send empty string.
    // If newPhotoFile exists, we send the preview (for local optimistic UI) but the file is uploaded separately.
    // If neither, we keep the existing photo.
    let photoToSave = editingEmployee?.photo || '';
    if (isPhotoRemoved) {
        photoToSave = '';
    } else if (newPhotoFile && photoPreview) {
        photoToSave = photoPreview;
    }

    const finalSectorId = selectedSectorId || editingEmployee?.sectorId || '';
    const departmentName = sectors.find(s => s.id === finalSectorId)?.name || '';

    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', 
      role: role || 'Cargo', 
      gender, 
      contact, 
      startDate,
      salary: parseFloat(salary) || 0, 
      department: departmentName,
      sectorId: finalSectorId, 
      status: 'Ativo', 
      scheduleType, 
      shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours: scheduleType === 'Intermitente' ? '' : workingHours, 
      fixedDayOff: scheduleType === '6x1' ? fixedDayOff : '', 
      sundayOffs: scheduleType === '6x1' ? sundayOffs : [], 
      weeklyDayOff: scheduleType === '6x1' ? fixedDayOff : '', 
      monthlySundayOff: '', 
      vacationStatus, 
      uniforms,
      photo: photoToSave
    };

    // Pass newPhotoFile as an array to syncToSheet via onSave
    onSave(newEmp, newPhotoFile ? [newPhotoFile] : undefined);
    resetEmployeeForm();
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSaveSector) {
      onSaveSector({ id: Date.now().toString(), name: sectorName, standardUniform: [] });
      setSectorName('');
      setIsAddingSector(false);
    }
  };

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => 
      (selectedSectorId ? e.sectorId === selectedSectorId : true) &&
      (e.name.toLowerCase().includes(searchTerm.toLowerCase()) || e.role.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [employees, selectedSectorId, searchTerm]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm w-full md:w-auto">
          <button onClick={() => { setActiveTab('LISTA'); setSelectedSectorId(null); }} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'LISTA' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>
            Colaboradores
          </button>
          <button onClick={() => setActiveTab('SETORES')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'SETORES' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>
            Setores
          </button>
        </div>

        {activeTab === 'LISTA' && (
          <div className="flex gap-3 w-full md:w-auto">
            <div className="relative flex-1 md:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
              <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 outline-none text-xs font-bold bg-white" />
            </div>
            {selectedSectorId && (
              <button onClick={() => setIsAddingEmployee(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                <Plus size={18} /> <span>Novo</span>
              </button>
            )}
          </div>
        )}
      </div>

      {activeTab === 'SETORES' ? (
        <div className="space-y-6">
           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              <button onClick={() => setIsAddingSector(true)} className="bg-white border-2 border-dashed border-slate-200 hover:border-blue-300 h-40 rounded-[2rem] flex flex-col items-center justify-center text-slate-400 hover:text-blue-500 transition-all group">
                 <PlusCircle size={32} className="mb-2 group-hover:scale-110 transition-transform"/>
                 <span className="font-bold text-xs uppercase">Novo Setor</span>
              </button>
              {sectors.map(sec => (
                 <div key={sec.id} className="relative group">
                    {onDeleteSector && (
                      <button onClick={() => onDeleteSector(sec.id)} className="absolute top-4 right-4 z-10 p-2 bg-white/80 hover:bg-white text-slate-300 hover:text-rose-500 rounded-full shadow-sm opacity-0 group-hover:opacity-100 transition-all">
                         <Trash2 size={16}/>
                      </button>
                    )}
                    <button onClick={() => { setSelectedSectorId(sec.id); setActiveTab('LISTA'); }} className="w-full bg-white h-40 rounded-[2rem] border border-slate-50 shadow-sm hover:shadow-xl transition-all flex flex-col items-center justify-center p-6">
                       <Briefcase size={28} className="text-slate-300 mb-3" />
                       <h3 className="text-lg font-black text-slate-800">{sec.name}</h3>
                       <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">{employees.filter(e => e.sectorId === sec.id).length} Colaboradores</p>
                    </button>
                 </div>
              ))}
           </div>
        </div>
      ) : (
        <div className="space-y-6">
           {selectedSectorId && (
              <div className="flex items-center space-x-2 text-slate-400 font-bold text-xs">
                 <button onClick={() => { setSelectedSectorId(null); setActiveTab('SETORES'); }}>Setores</button>
                 <ChevronRight size={14}/>
                 <span className="text-slate-800">{sectors.find(s => s.id === selectedSectorId)?.name}</span>
              </div>
           )}

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredEmployees.map(emp => (
                 <div key={emp.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-lg transition-all group relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-24 bg-gradient-to-b from-slate-50 to-transparent"></div>
                    <div className="relative flex flex-col items-center text-center space-y-3">
                       <div className="w-20 h-20 rounded-[1.5rem] shadow-xl overflow-hidden border-4 border-white">
                          {emp.photo ? (
                             <img src={emp.photo} alt={emp.name} className="w-full h-full object-cover"/>
                          ) : (
                             <div className={`w-full h-full flex items-center justify-center text-2xl font-black text-white ${emp.gender === 'F' ? 'bg-rose-300' : 'bg-blue-300'}`}>
                                {emp.name[0]}
                             </div>
                          )}
                       </div>
                       <div>
                          <h3 className="text-lg font-black text-slate-800 leading-tight">{emp.name}</h3>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">{emp.role}</p>
                       </div>
                    </div>

                    <div className="mt-6 pt-6 border-t border-slate-50 grid grid-cols-2 gap-4">
                       <div className="space-y-1">
                          <p className="text-[9px] font-black text-slate-300 uppercase flex items-center"><Phone size={10} className="mr-1"/> Contato</p>
                          <p className="text-xs font-bold text-slate-600 truncate">{emp.contact || 'N/A'}</p>
                       </div>
                       <div className="space-y-1 text-right">
                          <p className="text-[9px] font-black text-slate-300 uppercase flex items-center justify-end"><DollarSign size={10} className="mr-1"/> Salário</p>
                          <p className="text-xs font-bold text-slate-600">R$ {emp.salary.toLocaleString('pt-BR')}</p>
                       </div>
                       <div className="space-y-1">
                          <p className="text-[9px] font-black text-slate-300 uppercase flex items-center"><Calendar size={10} className="mr-1"/> Admissão</p>
                          <p className="text-xs font-bold text-slate-600">{emp.startDate ? new Date(emp.startDate).toLocaleDateString() : 'N/A'}</p>
                       </div>
                       <div className="space-y-1 text-right">
                          <p className="text-[9px] font-black text-slate-300 uppercase flex items-center justify-end"><CalendarDays size={10} className="mr-1"/> Escala</p>
                          <p className="text-xs font-bold text-slate-600">{emp.scheduleType}</p>
                       </div>
                    </div>

                    <div className="mt-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                       <button onClick={() => handleEditEmployee(emp)} className="flex-1 py-2 bg-slate-50 text-slate-600 rounded-xl font-black text-[10px] uppercase hover:bg-blue-50 hover:text-blue-500 transition-colors flex items-center justify-center space-x-1">
                          <Edit2 size={12} /> <span>Editar</span>
                       </button>
                       <button onClick={() => onDelete(emp.id)} className="flex-1 py-2 bg-slate-50 text-slate-600 rounded-xl font-black text-[10px] uppercase hover:bg-rose-50 hover:text-rose-500 transition-colors flex items-center justify-center space-x-1">
                          <Trash2 size={12} /> <span>Excluir</span>
                       </button>
                    </div>
                 </div>
              ))}
              {filteredEmployees.length === 0 && (
                 <div className="col-span-full py-20 text-center">
                    <p className="text-slate-300 font-bold italic">Nenhum colaborador encontrado.</p>
                 </div>
              )}
           </div>
        </div>
      )}

      {/* Modal ADD SECTOR */}
      {isAddingSector && (
         <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
                <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
                   <h3 className="font-black text-slate-800">Novo Setor</h3>
                   <button onClick={() => setIsAddingSector(false)}><X size={24} className="text-slate-300"/></button>
                </div>
                <form onSubmit={handleSaveSectorSubmit} className="p-6 space-y-4">
                   <input type="text" value={sectorName} onChange={e => setSectorName(e.target.value)} placeholder="Nome do Setor" className="w-full px-4 py-3 rounded-xl border-2 font-bold text-slate-800 outline-none focus:border-blue-400" required />
                   <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black text-xs uppercase shadow-lg">Criar Setor</button>
                </form>
             </div>
          </div>
      )}

      {/* Modal ADD/EDIT EMPLOYEE */}
      {isAddingEmployee && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden max-h-[90vh] flex flex-col">
              <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                 <div>
                    <h2 className="text-xl font-black text-slate-800">{editingEmployee ? 'Editar Colaborador' : 'Novo Colaborador'}</h2>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{sectors.find(s => s.id === selectedSectorId)?.name}</p>
                 </div>
                 <button onClick={resetEmployeeForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveEmployeeSubmit} className="p-8 overflow-y-auto space-y-6">
                 <div className="flex flex-col items-center mb-6">
                    <div className="relative w-24 h-24 rounded-[2rem] bg-slate-100 overflow-hidden border-4 border-white shadow-lg group cursor-pointer hover:brightness-95 transition-all">
                       {photoPreview ? (
                          <>
                            <img src={photoPreview} alt="Preview" className="w-full h-full object-cover" />
                            <div className="absolute inset-0 bg-black/30 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity" onClick={() => fileInputRef.current?.click()}>
                               <Camera className="text-white" size={24}/>
                            </div>
                          </>
                       ) : (
                          <div className="w-full h-full flex flex-col items-center justify-center text-slate-300" onClick={() => fileInputRef.current?.click()}>
                             <Camera size={24} />
                             <span className="text-[8px] font-black uppercase mt-1">Foto</span>
                          </div>
                       )}
                    </div>

                    {photoPreview && (
                        <button 
                            type="button"
                            onClick={handleRemovePhoto}
                            className="mt-2 text-[10px] font-black text-rose-500 uppercase flex items-center hover:text-rose-700"
                        >
                            <Trash2 size={12} className="mr-1" /> Remover Foto
                        </button>
                    )}
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*" />
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <div className="col-span-2">
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Nome Completo</label>
                       <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold text-slate-800" required />
                    </div>
                    <div>
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Cargo / Função</label>
                       <input type="text" value={role} onChange={e => setRole(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold text-slate-800" required />
                    </div>
                    <div>
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Gênero</label>
                       <div className="flex bg-slate-50 p-1 rounded-xl">
                          <button type="button" onClick={() => setGender('M')} className={`flex-1 py-2 rounded-lg text-xs font-black uppercase transition-all ${gender === 'M' ? 'bg-white shadow-sm text-blue-500' : 'text-slate-400'}`}>Masc</button>
                          <button type="button" onClick={() => setGender('F')} className={`flex-1 py-2 rounded-lg text-xs font-black uppercase transition-all ${gender === 'F' ? 'bg-white shadow-sm text-rose-500' : 'text-slate-400'}`}>Fem</button>
                       </div>
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <div>
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Contato</label>
                       <input type="text" value={contact} onChange={e => setContact(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold text-slate-800" placeholder="(00) 00000-0000" />
                    </div>
                    <div>
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Salário</label>
                       <input type="number" value={salary} onChange={e => setSalary(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold text-slate-800" placeholder="R$ 0,00" />
                    </div>
                 </div>

                 <div className="p-6 bg-slate-50 rounded-[2rem] space-y-4">
                    <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Detalhes da Escala</h3>
                    <div className="grid grid-cols-2 gap-4">
                        <select value={scheduleType} onChange={e => setScheduleType(e.target.value as any)} className="w-full px-4 py-3 rounded-xl border border-slate-200 outline-none font-bold text-slate-800 bg-white">
                           <option value="6x1">Escala 6x1</option>
                           <option value="12x36">Escala 12x36</option>
                           <option value="Intermitente">Intermitente</option>
                        </select>
                        <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 outline-none font-bold text-slate-800 bg-white" />
                    </div>

                    {scheduleType === '6x1' && (
                       <div className="space-y-4 animate-in fade-in">
                          <div>
                             <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Folga Fixa Semanal</label>
                             <div className="grid grid-cols-4 gap-2">
                                {['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'].map(d => (
                                   <button key={d} type="button" onClick={() => setFixedDayOff(d)} className={`py-2 rounded-lg text-[10px] font-black border uppercase transition-all ${fixedDayOff === d ? 'bg-slate-800 text-white border-slate-800' : 'bg-white border-slate-200 text-slate-400'}`}>{d.substr(0, 3)}</button>
                                ))}
                             </div>
                          </div>
                          <div>
                             <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Domingos de Folga (no mês)</label>
                             <div className="flex gap-2">
                                {[1, 2, 3, 4, 5].map(n => (
                                   <button key={n} type="button" onClick={() => {
                                      if (sundayOffs.includes(n)) setSundayOffs(sundayOffs.filter(i => i !== n));
                                      else setSundayOffs([...sundayOffs, n]);
                                   }} className={`w-10 h-10 rounded-lg font-black border transition-all ${sundayOffs.includes(n) ? 'bg-blue-500 text-white border-blue-500' : 'bg-white border-slate-200 text-slate-400'}`}>{n}º</button>
                                ))}
                             </div>
                          </div>
                       </div>
                    )}
                 </div>

                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 hover:brightness-110" style={{ backgroundColor: theme.primary }}>Salvar Colaborador</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

