                         {role !== 'FUNCIONARIO' && <button onClick={() => onDeleteSupplier(sup.id)} className="p-2 bg-white rounded-full text-slate-400 hover:text-rose-500 shadow-sm"><Trash2 size={14}/></button>}
                      </div>
                   </div>
                ))}
            </div>
         </div>
