                        type="text" 
                        value={sectorName} 
                        onChange={e => setSectorName(e.target.value)} 
                        placeholder="Ex: Recepção" 
                        className="w-full px-4 py-3 rounded-xl border-2 font-bold text-slate-800 outline-none focus:border-blue-400" 
                        required 
                      />
