                           type="text" 
                           value={newRole} 
                           onChange={e => setNewRole(e.target.value)} 
                           placeholder="Novo Cargo (Ex: Recepcionista)" 
                           className="flex-1 px-4 py-2 rounded-xl border-2 font-bold text-sm" 
                         />
