                           type="text" 
                           value={newSectorUniformName} 
                           onChange={e => setNewSectorUniformName(e.target.value)} 
                           placeholder="Item (Ex: Camisa)" 
                           className="flex-1 px-4 py-2 rounded-xl border-2 font-bold text-sm" 
                         />
